function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(v,d=2){if(v===null||v===undefined||v==='')return '—'; const n=Number(v); return Number.isFinite(n)?n.toFixed(d).replace(/\.00$/,''):esc(v);}
function fmtBytes(v){const n=Number(v||0);if(!Number.isFinite(n)||n<=0)return 'size unavailable';if(n<1024)return `${n} B`;if(n<1024**2)return `${(n/1024).toFixed(1)} KB`;if(n<1024**3)return `${(n/1024**2).toFixed(1)} MB`;return `${(n/1024**3).toFixed(2)} GB`;}
function fmtElapsed(seconds){const n=Math.max(0,Math.round(Number(seconds||0)));if(n<60)return `${n}s`;const m=Math.floor(n/60),sec=n%60;return `${m}m ${String(sec).padStart(2,'0')}s`;}
function importedFileRow(f,kind){const detail=kind==='survey'?`${f.records||0} target record${Number(f.records||0)===1?'':'s'}`:`${f.pages||0} page${Number(f.pages||0)===1?'':'s'}`;let when='';try{when=f.imported_at?` · ${new Date(f.imported_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:''}catch{}return `<div class="imported-file-row"><span class="imported-file-icon">${kind==='survey'?'⇧':'▤'}</span><div class="imported-file-main"><strong title="${esc(f.name)}">${esc(f.name)}</strong><small>${fmtBytes(f.size_bytes)} · ${detail}${when}</small></div><span class="file-ready">✓ Ready</span></div>`;}
function renderImportedFiles(){if(!state)return;const survey=state.survey_files||[],field=state.fieldbook_files||[];const total=survey.length+field.length;$('#importedFilesCount').textContent=`${total} file${total===1?'':'s'}`;$('#surveyImportedCount').textContent=survey.length;$('#fieldbookImportedCount').textContent=field.length;$('#surveyImportedList').innerHTML=survey.length?survey.map(f=>importedFileRow(f,'survey')).join(''):'<div class="empty-state compact">No survey files imported.</div>';$('#fieldbookImportedList').innerHTML=field.length?field.map(f=>importedFileRow(f,'fieldbook')).join(''):'<div class="empty-state compact">No field-book files imported.</div>';}
function importUi(kind){const survey=kind==='survey';return {box:$(survey?'#surveyImportProgress':'#fieldbookImportProgress'),stage:$(survey?'#surveyImportStage':'#fieldbookImportStage'),percent:$(survey?'#surveyImportPercent':'#fieldbookImportPercent'),bar:$(survey?'#surveyImportBar':'#fieldbookImportBar'),detail:$(survey?'#surveyImportDetail':'#fieldbookImportDetail')};}
function renderImportProgress(kind,pct,stage,detail,running=true){const u=importUi(kind);if(!u.box)return;u.box.classList.remove('hidden');const p=Math.max(0,Math.min(100,Math.round(Number(pct||0))));u.stage.textContent=stage||'Working…';u.percent.textContent=`${p}%`;u.bar.style.width=`${p}%`;u.box.classList.toggle('complete',!running&&p>=100);if(u.detail)u.detail.textContent=detail||'';$('#importSurveyBtn').disabled=!!running;$('#importFieldbookBtn').disabled=!!running;}
function renderImportJob(job){if(!job||!job.kind||job.phase==='idle')return;const kind=job.kind==='survey'?'survey':'fieldbook';const bits=[];if(job.current_file&&job.total_files)bits.push(`File ${job.current_file}/${job.total_files}`);if(job.current_page&&job.total_pages)bits.push(`Page ${job.current_page}/${job.total_pages}`);if(job.elapsed_seconds!==undefined)bits.push(`Elapsed ${fmtElapsed(job.elapsed_seconds)}`);renderImportProgress(kind,job.percent,(job.phase||'working').replaceAll('_',' '),bits.join(' · ')||job.message||'',job.running);const msg=$(kind==='survey'?'#surveyImportMsg':'#fieldbookImportMsg');if(msg&&job.message)msg.textContent=job.message;}
function renderClientUpload(kind,rawPct,loaded,total){const overall=Math.min(29,Math.max(1,Math.round(Number(rawPct||0)*.29)));renderImportProgress(kind,overall,'uploading',`Uploaded ${fmtBytes(loaded)} of ${fmtBytes(total)} · ${Math.round(rawPct)}% file transfer`,true);}
function startImportPolling(){if(importTimer)return;importTimer=setInterval(async()=>{try{const j=await api('/api/import-job');renderImportJob(j);if(!j.running&&j.phase!=='idle'){clearInterval(importTimer);importTimer=null;if(j.phase==='complete'){await loadState()}}}catch{}},500);}
async function api(url,opts={}){
  const requestOpts={...opts};
  const method=String(requestOpts.method||'GET').toUpperCase();
  const timeoutMs=requestOpts.timeoutMs===undefined?(method==='GET'?15000:0):Number(requestOpts.timeoutMs||0);
  delete requestOpts.timeoutMs;
  let timer=null, controller=null;
  if(timeoutMs>0&&!requestOpts.signal){controller=new AbortController();requestOpts.signal=controller.signal;timer=setTimeout(()=>controller.abort(),timeoutMs)}
  try{
    const res=await fetch(url,requestOpts); if(!res.ok){let msg=`HTTP ${res.status}`; try{const d=await res.json();const detail=d.detail||d.message;if(typeof detail==='string')msg=detail;else if(detail&&typeof detail==='object')msg=detail.message||JSON.stringify(detail)}catch{try{msg=await res.text()}catch{}} throw new Error(msg)}
    const ct=res.headers.get('content-type')||''; return ct.includes('json')?res.json():res;
  }catch(e){if(e?.name==='AbortError')throw new Error(`Request timed out after ${Math.round(timeoutMs/1000)} seconds: ${url}`);throw e}
  finally{if(timer)clearTimeout(timer)}
}
function toast(msg,type='good'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;$('#toastStack').append(el);setTimeout(()=>el.remove(),4200);}
function isTyping(){const e=document.activeElement;return e&&['INPUT','TEXTAREA','SELECT'].includes(e.tagName);}
