function rememberSharedUiPrefs(p){if(!p)return;localStorage.setItem(SURVEYSYNC_APPEARANCE_KEY,p.appearance||'system');localStorage.setItem(SURVEYSYNC_PRODUCT_THEME_KEY,p.theme||'classic');localStorage.setItem(SURVEYSYNC_ACCENT_KEY,p.accent||'default');localStorage.setItem('fbs-theme',p.appearance||'system');localStorage.setItem(PRODUCT_THEME_PREF_KEY,p.theme||'classic');localStorage.setItem('fbs-accent',p.accent||'default')}
function scheduleSharedUiSync(){clearTimeout(sharedUiSyncTimer);sharedUiSyncTimer=setTimeout(async()=>{try{await api('/api/v9/config/ui',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(currentSharedUiPrefs()),timeoutMs:5000})}catch(e){console.warn('SurveySync UI preference sync failed',e)}},80)}
async function loadSharedUiPrefs(){try{const p=await api('/api/v9/config/ui',{timeoutMs:5000});rememberSharedUiPrefs(p);applyTheme(p.appearance||'system',false);applyProductTheme(p.theme||'classic',false);applyAccent(p.accent||'default',false);return p}catch(e){console.warn('SurveySync UI preference load failed',e);return null}}
function startupProductTheme(){
  const shared=localStorage.getItem(SURVEYSYNC_PRODUCT_THEME_KEY);
  if(shared&&PRODUCT_THEMES[shared])return shared;
  if(localStorage.getItem(PRODUCT_THEME_USER_SET_KEY)!=='1')return 'classic';
  const key=localStorage.getItem(PRODUCT_THEME_PREF_KEY)||'classic';
  return PRODUCT_THEMES[key]?key:'classic';
}
function resolveTheme(mode){return mode==='system'?(matchMedia('(prefers-color-scheme:light)').matches?'light':'dark'):mode;}
function applyTheme(mode,persist=true){if(!['system','light','dark'].includes(mode))mode='system';const theme=resolveTheme(mode);document.documentElement.dataset.theme=theme;document.documentElement.dataset.themeMode=mode;if(persist){localStorage.setItem(SURVEYSYNC_APPEARANCE_KEY,mode);localStorage.setItem('fbs-theme',mode);scheduleSharedUiSync()}const tt=$('#themeText'),tg=$('#themeGlyph');if(tt)tt.textContent=mode[0].toUpperCase()+mode.slice(1);if(tg)tg.textContent=mode==='light'?'☀':mode==='dark'?'◒':'◐';if($('#globalAppearanceText'))$('#globalAppearanceText').textContent=mode[0].toUpperCase()+mode.slice(1);if($('#globalAppearanceGlyph'))$('#globalAppearanceGlyph').textContent=mode==='light'?'☀':mode==='dark'?'◒':'◐';updateOptionControls();}
function cycleTheme(){const m=document.documentElement.dataset.themeMode||'system';applyTheme(m==='system'?'light':m==='light'?'dark':'system');}
