window.addEventListener('storage',e=>{if(e.key===SURVEYSYNC_APPEARANCE_KEY)applyTheme(localStorage.getItem(SURVEYSYNC_APPEARANCE_KEY)||'system',false);if(e.key===SURVEYSYNC_PRODUCT_THEME_KEY)applyProductTheme(localStorage.getItem(SURVEYSYNC_PRODUCT_THEME_KEY)||'classic',false);if(e.key===SURVEYSYNC_ACCENT_KEY)applyAccent(localStorage.getItem(SURVEYSYNC_ACCENT_KEY)||'default',false)});

