$('#profileSelect').onchange=async e=>{if(!e.target.value)return;await api('/api/select-profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:e.target.value})});toast(`Selected ${e.target.value}`);await loadState();await loadProfiles();};
