async function importFileArray(files,endpoint,msg){files=[...files];if(!files.length){toast('Choose at least one file.','error');return false}const kind=endpoint.includes('survey')?'survey':'fieldbook';const fd=new FormData();files.forEach(f=>fd.append('files',f));$(msg).textContent=`Starting ${files.length} file${files.length===1?'':'s'}…`;renderImportProgress(kind,1,'starting',`Preparing ${files.length} file${files.length===1?'':'s'}…`,true);startImportPolling();try{await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',endpoint,true);xhr.upload.onprogress=e=>{if(e.lengthComputable)renderClientUpload(kind,(e.loaded/e.total)*100,e.loaded,e.total)};xhr.onerror=()=>reject(new Error('Upload connection failed.'));xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){resolve(xhr.responseText)}else{let message=`HTTP ${xhr.status}`;try{const d=JSON.parse(xhr.responseText||'{}');const detail=d.detail||d.message;message=typeof detail==='string'?detail:(detail?.message||message)}catch{}reject(new Error(message))}};xhr.send(fd)});$(msg).textContent='Import complete.';toast(`${files.length} file${files.length===1?'':'s'} imported`);await loadState();return true}catch(e){$(msg).textContent=e.message;toast(e.message,'error');try{const j=await api('/api/import-job');renderImportJob(j)}catch{}return false}}
async function importFiles(input,endpoint,msg){return importFileArray([...input.files],endpoint,msg)}
