async function renderFieldbookProfilePanel(){
  const panel=$('#fieldbookProfilePanel');if(!panel)return;const books=(state?.fieldbook_files||[]).filter(x=>x.kind==='fieldbook');panel.classList.toggle('hidden',!books.length);if(!books.length)return;await ensureFieldNoteProfiles();
  const source=$('#fieldbookProfileSource'),profile=$('#fieldbookProfileSelect');const priorSource=source?.value;source.innerHTML=books.map(b=>`<option value="${esc(b.name)}">${esc(b.name)} · ${Number(b.pages||0)} pages</option>`).join('');if(priorSource&&books.some(b=>b.name===priorSource))source.value=priorSource;
  const book=books.find(b=>b.name===source.value)||books[0];if(!book)return;profile.innerHTML=`<option value="AUTO">Auto-detect per page</option>`+fieldNoteProfiles.map(p=>`<option value="${esc(p.profile_id)}">${esc(p.name)}</option>`).join('');profile.value=book.field_note_profile||'AUTO';
  const selected=profile.value,status=$('#fieldbookProfileStatus'),hint=$('#fieldbookProfileHint');if(status){status.textContent=selected==='AUTO'?'Auto':(book.field_note_profile_mode==='trained'?'Trained':'Selected');status.classList.toggle('good',selected!=='AUTO')}if(hint){const p=fieldNoteProfileById(selected);hint.textContent=selected==='AUTO'?'Auto mode leaves this book unforced. SurveySync compares installed field-note profiles during analysis and routes uncertain pages to review.':`${p?.name||selected} is the default for this book. Individual pages can still override it in the Trainer.`}
}
async function assignFieldbookProfile(sourceName,profileId,mode='user'){const d=await api('/api/fieldbook-profile-assignment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_name:sourceName,profile_id:profileId,mode})});await loadState();return d}
async function previewFieldbookTrainingPages(sourceName){if(!sourceName)return;const d=await api(`/api/fieldbook-training-preview?source_name=${encodeURIComponent(sourceName)}&limit=5`);const pages=d.pages||[];const body=pages.length?`<div class="fieldbook-preview-grid">${pages.map(p=>`<button class="fieldbook-preview-page" data-page="${esc(p.page_id)}"><img src="${esc(p.url)}" alt="Page ${p.page_number}"/><span>Page ${p.page_number}${p.page_type&&p.page_type!=='unknown'?` · ${esc(p.page_type)}`:''}</span></button>`).join('')}</div><div class="row" style="margin-top:14px"><button id="previewTrainBookBtn" class="btn primary">Train from these pages</button><button class="btn secondary" onclick="document.querySelector('#modalClose').click()">Close</button></div>`:'<div class="empty-state">No pages are available for this field book.</div>';openModal(`Training preview · ${sourceName}`,body,'FIELD NOTE PROFILE');$$('.fieldbook-preview-page',$('#modalBody')).forEach(b=>b.onclick=()=>{trainerSourceContext=sourceName;switchTab('training');setTimeout(()=>{const sel=$('#trainerPageSelect');if(sel&&[...sel.options].some(o=>o.value===b.dataset.page)){sel.value=b.dataset.page;showTrainerPage(b.dataset.page)}},120);$('#modalClose')?.click()});$('#previewTrainBookBtn')?.addEventListener('click',()=>{$('#modalClose')?.click();openFieldBookTrainer(sourceName)})}
function openFieldBookTrainer(sourceName){trainerSourceContext=sourceName||'';const book=(state?.fieldbook_files||[]).find(x=>x.name===trainerSourceContext);if(book?.field_note_profile&&book.field_note_profile!=='AUTO')selectedFieldNoteProfileId=book.field_note_profile;switchTab('training')}
$('#fieldbookProfileSource')?.addEventListener('change',()=>renderFieldbookProfilePanel().catch(e=>toast(e.message,'error')));
$('#fieldbookProfileSelect')?.addEventListener('change',async e=>{const source=$('#fieldbookProfileSource')?.value;if(!source)return;try{await assignFieldbookProfile(source,e.target.value,'user');toast(e.target.value==='AUTO'?'Field book returned to automatic profile detection.':'Field-note profile assigned to this field book.','good')}catch(err){toast(err.message,'error')}});
$('#fieldbookPreviewTrainingBtn')?.addEventListener('click',()=>previewFieldbookTrainingPages($('#fieldbookProfileSource')?.value).catch(e=>toast(e.message,'error')));
