function pointRangeCsv(summary){
  const q=v=>`"${String(v??'').replaceAll('"','""')}"`;
  const rows=[['Available Point Range','Capacity','Priority','Notes'],...(summary.recommendations||[]).map(r=>[r.range,r.capacity_label,r.priority,r.notes])];
  return '\ufeff'+rows.map(row=>row.map(q).join(',')).join('\r\n')+'\r\n';
}
function downloadPointRangeSummary(summary){
  const blob=new Blob([pointRangeCsv(summary)],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='available_point_ranges.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function renderPointRangeSummary(summary){
  const rows=(summary.recommendations||[]).map(r=>`<tr><td><strong>${esc(r.range)}</strong>${r.priority==='Safest'?'<div class="hint">Safest new-series option</div>':''}</td><td>${esc(r.capacity_label)}</td><td><span class="status ${r.priority==='Safest'?'YES':'PENDING'}">${esc(r.priority)}</span></td><td>${esc(r.notes)}</td></tr>`).join('');
  const omitted=Number(summary.smaller_gap_count||0);
  const body=`<div class="note-box good"><strong>${Number(summary.used_count||0).toLocaleString()} occupied PointIDs reviewed</strong><div class="hint">Used range: ${Number(summary.lowest_used||0).toLocaleString()} through ${Number(summary.highest_used||0).toLocaleString()}. No PointID shown below overlaps a number found in the uploaded file${summary.ignored_point_ids?` · ${Number(summary.ignored_point_ids).toLocaleString()} non-numeric ID${Number(summary.ignored_point_ids)===1?' was':'s were'} ignored`:''}.</div></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Available Point Range</th><th>Capacity</th><th>Priority</th><th>Notes</th></tr></thead><tbody>${rows||'<tr><td colspan="4">No crew-sized gaps were found.</td></tr>'}</tbody></table></div>${omitted?`<div class="hint" style="margin-top:10px">${omitted} smaller gap${omitted===1?'':'s'} under ${Number(summary.minimum_capacity||100)} points ${omitted===1?'was':'were'} intentionally omitted from the crew-allocation table.</div>`:''}<div class="row" style="margin-top:14px"><button id="downloadPointRangeCsv" class="btn primary">Download CSV</button><button class="btn secondary" onclick="document.querySelector('#modalClose').click()">Close</button></div>`;
  openModal('Available Point Ranges',body,'CREW POINT ALLOCATION');
  document.getElementById('downloadPointRangeCsv')?.addEventListener('click',()=>downloadPointRangeSummary(summary));
}
async function analyzeAvailablePointRanges(files){
  files=[...(files||[])];
  if(!files.length){$('#pointRangeFiles')?.click();return}
  const fd=new FormData();files.forEach(f=>fd.append('files',f));
  const btn=$('#pointRangesBtn');const old=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Analyzing…'}
  try{
    const res=await fetch('/api/survey/point-range-summary',{method:'POST',body:fd});
    if(!res.ok){let msg=`HTTP ${res.status}`;try{const d=await res.json();msg=d.detail||d.message||msg}catch{try{msg=await res.text()}catch{}}throw new Error(typeof msg==='string'?msg:JSON.stringify(msg))}
    const summary=await res.json();renderPointRangeSummary(summary);toast(`${Number(summary.recommended_count||0)} crew allocation option${Number(summary.recommended_count||0)===1?'':'s'} found`,'good');
  }catch(e){toast(e.message,'error')}
  finally{if(btn){btn.disabled=false;btn.textContent=old||'Point ranges'}}
}
$('#pointRangesBtn')?.addEventListener('click',()=>{const staged=[...($('#surveyFiles')?.files||[])];if(staged.length)analyzeAvailablePointRanges(staged);else $('#pointRangeFiles')?.click()});
$('#pointRangeFiles')?.addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';if(files.length)analyzeAvailablePointRanges(files)});

