const SURVEY_EXTS=new Set(['.csv','.txt','.tsv']);['.pnezd','.asc','.job','.jxl','.xml'].forEach(x=>SURVEY_EXTS.add(x)); const FIELD_EXTS=new Set(['.pdf','.png','.jpg','.jpeg','.webp']);
function fileExt(name){const i=String(name||'').lastIndexOf('.');return i>=0?String(name).slice(i).toLowerCase():''}
function uniqueFiles(files){const seen=new Set();return [...files].filter(f=>{const k=`${f.name}|${f.size}|${f.lastModified}`;if(seen.has(k))return false;seen.add(k);return true})}
function classifyDropped(files){const out={survey:[],fieldbook:[],project:[],other:[]};for(const f of uniqueFiles(files)){const x=fileExt(f.name);if(SURVEY_EXTS.has(x))out.survey.push(f);else if(FIELD_EXTS.has(x))out.fieldbook.push(f);else if(x==='.fbs')out.project.push(f);else out.other.push(f)}return out}
function canTransferFiles(e){return !!e.dataTransfer&&[...e.dataTransfer.types].includes('Files')}
function setDropOverlay(show,title='Drop files into FieldBook Sync',hint='Survey TXT/CSV/TSV · field-book PDF/images · .fbs projects'){const o=$('#globalDropOverlay');if(!o)return;o.classList.toggle('hidden',!show);o.setAttribute('aria-hidden',show?'false':'true');document.body.classList.toggle('file-dragging',show);if(show){$('#globalDropTitle').textContent=title;$('#globalDropHint').textContent=hint}}
function mergeFileLists(a,b){return uniqueFiles([...(a||[]),...(b||[])])}
function stageInputFiles(input,files,labelId,empty){try{const dt=new DataTransfer();mergeFileLists([...input.files],files).forEach(f=>dt.items.add(f));input.files=dt.files;fileLabel(input,labelId,empty);return true}catch{return false}}
function batchLabel(){$('#batchRawSurveyLabel').textContent=batchRawSurveys.length?`${batchRawSurveys.length} survey file(s) ready`:'Drop survey files here or click to browse';$('#batchRawFieldbookLabel').textContent=batchRawFieldbooks.length?`${batchRawFieldbooks.length} field-book file(s) ready`:'Drop field books here or click to browse'}
async function openDroppedProject(file){const fd=new FormData();fd.append('file',file);try{await api('/api/project/import',{method:'POST',body:fd});toast(`Opened ${file.name}`);await loadState();await loadProfiles();await refreshResults();switchTab('dashboard')}catch(err){toast(err.message,'error')}}
async function queueDroppedProjects(files){files=[...files];if(!files.length)return;const fd=new FormData();files.forEach(f=>fd.append('files',f));try{await api('/api/batch/import-projects',{method:'POST',body:fd});toast(`${files.length} project${files.length===1?'':'s'} added to queue`);await loadBatch()}catch(err){toast(err.message,'error')}}
async function handleDashboardDrop(files){const g=classifyDropped(files);if(g.project.length){if(g.project.length===1&&!g.survey.length&&!g.fieldbook.length){await openDroppedProject(g.project[0]);return}await queueDroppedProjects(g.project)}if(g.survey.length){if(!state?.selected_profile){toast('Survey files are staged. Select a client profile, then click Import survey.','warn');stageInputFiles($('#surveyFiles'),g.survey,'#surveyFileLabel','or click to browse · TXT, CSV, TSV, PNEZD, JOB, JXL') }else await importFileArray(g.survey,'/api/import-survey','#surveyImportMsg')}if(g.fieldbook.length)await importFileArray(g.fieldbook,'/api/import-fieldbook','#fieldbookImportMsg');if(g.other.length)toast(`Ignored ${g.other.length} unsupported file${g.other.length===1?'':'s'}.`,'warn')}
function bindDropZone(zoneSelector,onFiles){const zone=$(zoneSelector);if(!zone)return;let depth=0;zone.addEventListener('dragenter',e=>{if(!canTransferFiles(e))return;e.preventDefault();e.stopPropagation();depth++;zone.classList.add('drag-active');setDropOverlay(false)});zone.addEventListener('dragover',e=>{if(!canTransferFiles(e))return;e.preventDefault();e.stopPropagation();if(e.dataTransfer)e.dataTransfer.dropEffect='copy';zone.classList.add('drag-active')});zone.addEventListener('dragleave',e=>{if(!canTransferFiles(e))return;e.preventDefault();e.stopPropagation();depth=Math.max(0,depth-1);if(!depth)zone.classList.remove('drag-active')});zone.addEventListener('drop',async e=>{if(!canTransferFiles(e))return;e.preventDefault();e.stopPropagation();depth=0;zone.classList.remove('drag-active');setDropOverlay(false);const files=[...e.dataTransfer.files];if(files.length)await onFiles(files)})}
bindDropZone('#surveyDropzone',async files=>{const g=classifyDropped(files);if(g.survey.length){if(!state?.selected_profile){stageInputFiles($('#surveyFiles'),g.survey,'#surveyFileLabel','or click to browse · TXT, CSV, TSV, PNEZD, JOB, JXL');toast('Survey files staged. Select a client profile, then click Import survey.','warn')}else await importFileArray(g.survey,'/api/import-survey','#surveyImportMsg')}if(g.fieldbook.length||g.project.length||g.other.length)toast('Only survey TXT/CSV/TSV/PNEZD or Trimble JOB/JXL files are accepted in this drop area.','warn')});
bindDropZone('#fieldbookDropzone',async files=>{const g=classifyDropped(files);if(g.fieldbook.length)await importFileArray(g.fieldbook,'/api/import-fieldbook','#fieldbookImportMsg');if(g.survey.length||g.project.length||g.other.length)toast('Only field-book PDFs or images are accepted in this drop area.','warn')});
bindDropZone('#batchSurveyDropzone',files=>{const g=classifyDropped(files);batchRawSurveys=mergeFileLists(batchRawSurveys,g.survey);batchLabel();if(g.survey.length)toast(`${g.survey.length} survey file${g.survey.length===1?'':'s'} ready for batch pairing`);if(g.fieldbook.length||g.project.length||g.other.length)toast('Non-survey files were ignored in the survey drop area.','warn')});
bindDropZone('#batchFieldbookDropzone',files=>{const g=classifyDropped(files);batchRawFieldbooks=mergeFileLists(batchRawFieldbooks,g.fieldbook);batchLabel();if(g.fieldbook.length)toast(`${g.fieldbook.length} field-book file${g.fieldbook.length===1?'':'s'} ready for batch pairing`);if(g.survey.length||g.project.length||g.other.length)toast('Non-field-book files were ignored in the field-book drop area.','warn')});
document.addEventListener('dragenter',e=>{if(!canTransferFiles(e)||e.target.closest?.('.dropzone,.drop-mini'))return;e.preventDefault();globalDragDepth++;const batch=$('#tab-batch')?.classList.contains('active');setDropOverlay(true,batch?'Drop files into the batch queue':'Drop files to import',batch?'Survey files, field books, or .fbs projects · files are sorted automatically':'Survey files + field books can be dropped together · .fbs opens a project')});
document.addEventListener('dragover',e=>{if(!canTransferFiles(e))return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy'});
document.addEventListener('dragleave',e=>{if(!canTransferFiles(e))return;globalDragDepth=Math.max(0,globalDragDepth-1);if(!globalDragDepth)setDropOverlay(false)});
document.addEventListener('drop',async e=>{if(!canTransferFiles(e)||e.target.closest?.('.dropzone,.drop-mini'))return;e.preventDefault();globalDragDepth=0;setDropOverlay(false);const files=[...e.dataTransfer.files];if(!files.length)return;const g=classifyDropped(files);if($('#tab-batch')?.classList.contains('active')){if(g.project.length)await queueDroppedProjects(g.project);batchRawSurveys=mergeFileLists(batchRawSurveys,g.survey);batchRawFieldbooks=mergeFileLists(batchRawFieldbooks,g.fieldbook);batchLabel();if(g.survey.length||g.fieldbook.length)toast('Raw files sorted into the batch drop areas. Click Pair & queue raw jobs when ready.');if(g.other.length)toast(`${g.other.length} unsupported file${g.other.length===1?'':'s'} ignored.`,'warn')}else {switchTab('dashboard');await handleDashboardDrop(files)}});
$('#surveyIssuesBtn').onclick=async()=>{const items=await api('/api/survey/issues');openModal('Survey import issues',items.length?`<div class="table-wrap"><table><thead><tr><th>File</th><th>Row</th><th>Issue</th><th>Raw</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.source_file)}</td><td>${i.source_row}</td><td>${esc(i.message)}</td><td>${esc(i.raw)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No survey import issues.</div>','SURVEY QA');};
$('#rodBustBtn').onclick=async()=>{try{const d=await api('/api/survey/rod-height-busts');if(!d.enabled){openModal('Rod Height Bust QC','<p>Rod Height QC is disabled. Enable it under Settings → Derived intelligence.</p>','SURVEY QC');return}if(!d.survey_point_count){openModal('Rod Height Bust QC','<p>No survey points loaded. Select a code profile and import survey points on Home first. A field-book PDF is not required.</p>','SURVEY QC');return}const unit=esc(d.project_units||'project units');const rows=(d.items||[]);const summary=`<div class="note-box ${rows.length?'warning':'good'}"><strong>${rows.length?`${rows.length} likely rod-height bust candidate${rows.length===1?'':'s'}`:'No likely rod-height busts detected'}</strong><div class="hint">Radius ${fmt(d.settings?.search_radius,1)} ${unit} · slope threshold ${fmt(d.settings?.max_slope_percent,1)}% · round increments 0.50 / 1.00 / 2.00 · tolerance ${fmt(d.settings?.increment_tolerance,2)} ${unit}</div></div>`;const table=rows.length?`<div class="table-wrap"><table><thead><tr><th>Point</th><th>Elevation</th><th>Local expected</th><th>ΔZ</th><th>Nearest</th><th>Slope</th><th>Round increment</th><th>Confidence</th><th>Why</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.point_id)}</strong></td><td>${fmt(r.elevation,3)}</td><td>${fmt(r.expected_local_elevation,3)}</td><td>${fmt(r.signed_delta,3)}</td><td>${fmt(r.nearest_distance,2)} ${unit}</td><td>${fmt(r.slope_percent,1)}%</td><td>${fmt(r.matched_increment,2)}</td><td><span class="status ${r.severity==='HIGH'?'REVIEW':'PENDING'}">${fmt(r.confidence,0)}%</span></td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No candidate passed the configured proximity, slope, round-increment and neighborhood checks. This is not a guarantee that the survey is free of rod-height errors.</div>';openModal('Rod Height Bust QC',summary+table,'SURVEY QC');}catch(e){toast(e.message,'error')}};
$('#previewPagesBtn').onclick=showPages;$('#openFirstPageBtn').onclick=showPages;
async function showPages(){const pages=await api('/api/pages');if(!pages.length){toast('No field-book pages loaded.','error');return}openModal('Field-book pages',`<div class="page-grid">${pages.map(p=>`<button class="page-thumb" data-page="${esc(p.page_id)}"><img src="${p.enhanced_url||p.url}"/><span>${esc(p.source_name)} · Page ${p.page_number}</span></button>`).join('')}</div>`,'LOCAL PAGES');$$('.page-thumb',$('#modalBody')).forEach(b=>b.onclick=()=>openPageModal(b.dataset.page));}
function openPageModal(pageId,bbox=null,text=''){const overlay=bbox?bboxHtml(bbox):'';openModal('Field-book evidence',`<div class="image-frame"><div class="image-stage"><img src="/api/page/${encodeURIComponent(pageId)}?enhanced=1" onerror="this.src='/api/page/${encodeURIComponent(pageId)}'"/>${overlay}</div></div>${text?`<div class="raw-ocr" style="margin-top:10px">${esc(text)}</div>`:''}`,'PAGE REVIEW');}

// Analysis --------------------------------------------------------------------
async function startAnalysis(){try{const job=await api('/api/analyze',{method:'POST'});if(state)state.job=job;renderJob(job);toast('Analysis started');startJobPolling()}catch(e){toast(e.message,'error')}}
$('#analyzeBtn').onclick=startAnalysis;$('#analyzeHeroBtn').onclick=startAnalysis;$('#pauseBtn').onclick=async()=>{try{const j=state?.job||{};const endpoint=(j.paused||j.pause_requested)?'/api/resume-paused-analysis':'/api/pause-analysis';const job=await api(endpoint,{method:'POST'});if(state)state.job=job;renderJob(job);toast(endpoint.includes('resume')?'Resume requested':'Pause requested','good');startJobPolling()}catch(e){toast(e.message,'error')}};$('#cancelBtn').onclick=async()=>{await api('/api/cancel-analysis',{method:'POST'});toast('Cancel requested','good')};
async function refreshLiveViews(job=null){if(liveRefreshBusy)return;liveRefreshBusy=true;try{const [r,u,c,n]=await Promise.all([api('/api/results',{timeoutMs:120000}),api('/api/unmatched',{timeoutMs:120000}),api('/api/ocr/candidates',{timeoutMs:120000}),api('/api/network',{timeoutMs:120000})]);results=r;unmatched=u;candidates=c;network=n;resultsLoaded=true;resultsRevision=state?.project_revision??resultsRevision;if(state){state.ocr_candidate_count=candidates.length;state.network_edge_count=(network.edges||[]).length;state.result_count=results.length;state.unmatched_count=unmatched.length;const counts={YES:0,NO:0,REVIEW:0,NOT_FOUND:0};let qa=0;results.forEach(x=>{if(x.live_state==='PENDING_OCR')return;const s=x.status||'NOT_FOUND';counts[s]=(counts[s]||0)+1;if(x.qa_needs_review)qa++});state.status_counts=counts;state.qa_review_count=qa}renderResults();renderUnmatched();renderCandidates();renderNetwork();renderMetrics()}catch{}finally{liveRefreshBusy=false}}
function startJobPolling(){if(jobTimer)return;liveSeqSeen=-1;jobTimer=setInterval(async()=>{try{const job=await api('/api/job');if(state)state.job=job;renderJob(job);const seq=Number(job.live_update_seq||0);if(job.running&&seq!==liveSeqSeen){liveSeqSeen=seq;refreshLiveViews(job)}if(!job.running){clearInterval(jobTimer);jobTimer=null;liveSeqSeen=-1;await loadState();await Promise.all([refreshResults(),loadCandidates(),loadNetwork()]);if(job.complete)toast(job.message||'Analysis complete');else if(job.error)toast(job.error,'error')}}catch{}},750);}

// Results / review -------------------------------------------------------------
async function refreshResults(){[results,unmatched]=await Promise.all([api('/api/results',{timeoutMs:120000}),api('/api/unmatched',{timeoutMs:120000})]);resultsLoaded=true;resultsRevision=state?.project_revision??resultsRevision;renderResults();renderUnmatched();}
async function ensureResultsLoaded(){if(resultsLoaded&&resultsRevision===(state?.project_revision??resultsRevision)){renderResults();renderUnmatched();return}try{await refreshResults()}catch(e){toast(`Could not load results: ${e.message}`,'error')}}
function filteredResults(){const q=$('#resultSearch').value.trim().toLowerCase(),st=$('#statusFilter').value,rv=$('#reviewFilter').value,qc=$('#qcOnly').checked;return results.filter(r=>{const displayStatus=r.live_state==='PENDING_OCR'?'PENDING':r.live_state==='OCR_FOUND'?'OCR_FOUND':r.status;return (!q||[r.point_id,r.code,r.category,r.notes,r.dip_status].join(' ').toLowerCase().includes(q))&&(!st||displayStatus===st)&&(!rv||r.review_state===rv)&&(!qc||r.qa_needs_review||(r.qc_flags||[]).length)});}
function smartConf(r){const c=Number(r.smart_confidence||0);return `<div class="conf"><div class="conf-line"><div class="conf-bar"><i style="width:${Math.min(100,c)}%"></i></div><strong>${c.toFixed(0)}%</strong></div></div>`;}
function resultRowHtml(r){const live=r.live_state||'';const primary=live==='PENDING_OCR'?'PENDING OCR':live==='OCR_FOUND'?'OCR FOUND':String(r.status||'NOT_FOUND').replace('_',' ');const primaryClass=live==='PENDING_OCR'?'PENDING':live==='OCR_FOUND'?'OCR_FOUND':r.status;const dip=live==='PENDING_OCR'?'WAITING FOR OCR':live==='OCR_FOUND'?'INTERPRETATION PENDING':(r.qa_needs_review?'QA REVIEW':String(r.dip_status||'NOT FOUND').replace('_',' '));const dipClass=live==='PENDING_OCR'?'PENDING':live==='OCR_FOUND'?'OCR_FOUND':(r.qa_needs_review?'REVIEW':(r.dip_status||'NOT_FOUND'));return `<tr data-point="${esc(r.point_id)}"><td><strong>${esc(r.point_id)}</strong></td><td>${esc(r.code)}</td><td><span class="status ${primaryClass}">${esc(primary)}</span></td><td><span class="status ${dipClass}">${esc(dip)}</span></td><td>${smartConf(r)}</td><td>${r.pipes.length}</td><td>${(r.qc_flags||[]).length||r.qa_needs_review?`<span class="qc-badge">⚠ ${(r.qc_flags||[]).length+(r.qa_needs_review?1:0)}</span>`:'—'}</td><td><span class="review-badge ${r.review_state}">${live&&live!=='INTERPRETED'?'LIVE':r.review_state}</span></td><td><button class="btn subtle review-row">${live&&live!=='INTERPRETED'?'View':'Review'}</button></td></tr>`;}
function bindVisibleResultRows(){$$('#resultsTable .review-row').forEach(b=>b.onclick=()=>openResultReview(b.closest('tr').dataset.point));}
function renderResultWindow(reset=false){const wrap=$('#resultsTableWrap'),body=$('#resultsTable tbody'),rows=resultVirtual.rows;if(!wrap||!body)return;if(reset)wrap.scrollTop=0;$('#resultCountChip').textContent=`${rows.length} result${rows.length===1?'':'s'}`;if(!rows.length){body.innerHTML='<tr><td colspan="9"><div class="empty-state">No matching results.</div></td></tr>';return}if(rows.length<160){body.innerHTML=rows.map(resultRowHtml).join('');bindVisibleResultRows();return}const h=wrap.clientHeight||620,start=Math.max(0,Math.floor(wrap.scrollTop/resultVirtual.rowHeight)-resultVirtual.overscan),visible=Math.ceil(h/resultVirtual.rowHeight)+resultVirtual.overscan*2,end=Math.min(rows.length,start+visible),top=start*resultVirtual.rowHeight,bottom=(rows.length-end)*resultVirtual.rowHeight;body.innerHTML=`<tr class="virtual-spacer"><td colspan="9" style="height:${top}px"></td></tr>${rows.slice(start,end).map(resultRowHtml).join('')}<tr class="virtual-spacer"><td colspan="9" style="height:${bottom}px"></td></tr>`;bindVisibleResultRows();}
function renderResults(){resultVirtual.rows=filteredResults();renderResultWindow(true);}
['resultSearch','statusFilter','reviewFilter','qcOnly'].forEach(id=>$('#'+id).addEventListener('input',renderResults));$('#manualEntryBtn').onclick=openManualEntryWizard;$('#refreshResultsBtn').onclick=refreshResults;
$('#resultsTableWrap')?.addEventListener('scroll',()=>{if(resultVirtual.rows.length<160)return;cancelAnimationFrame(resultVirtual.raf);resultVirtual.raf=requestAnimationFrame(()=>renderResultWindow(false))},{passive:true});
function renderUnmatched(){$('#unmatchedCountChip').textContent=unmatched.length;$('#unmatchedTable tbody').innerHTML=unmatched.length?unmatched.map((u,i)=>`<tr><td><strong>${esc(u.point_id_raw||'Unknown')}</strong></td><td>${Math.round((u.confidence||0)*100)}%</td><td>${esc(u.source_name)}</td><td>${u.page_number}</td><td title="${esc(u.reason)}">${esc((u.reason||'').slice(0,80))}</td><td><button class="btn subtle" data-unmatched="${i}">View</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state">No unmatched evidence.</div></td></tr>';$$('[data-unmatched]').forEach(b=>b.onclick=()=>{const u=unmatched[+b.dataset.unmatched];openPageModal(u.page_id,u.bbox,u.reason)})}
function bboxHtml(b){if(!b||b.length!==4)return'';const[x1,y1,x2,y2]=b;return `<div class="bbox" style="left:${x1/10}%;top:${y1/10}%;width:${Math.max(1,(x2-x1)/10)}%;height:${Math.max(1,(y2-y1)/10)}%"></div>`;}
function pipeEditor(p={},i=0){return `<div class="pipe-card" data-pipe="${i}"><div class="row"><strong>Pipe ${i+1}</strong><span class="grow"></span><button class="icon-btn remove-pipe" title="Remove">×</button></div><div class="pipe-grid"><label>Dip / depth<input class="control p-dip" type="number" step="any" value="${p.dip??''}"/></label><label>Diameter (in)<input class="control p-dia" type="number" step="any" value="${p.diameter_in??''}"/></label><label>Material<input class="control p-mat" value="${esc(p.material||'')}"/></label><label>Written azimuth (°)<input class="control p-az" type="number" step="any" value="${p.azimuth_deg??''}"/></label><label>Sketch leader direction (°)<input class="control p-leader" type="number" step="any" value="${p.leader_direction_deg??''}"/></label><label>Written destination PointID<input class="control p-to" value="${esc(p.connected_point_raw||'')}" placeholder="e.g. to 3394"/></label></div>${p.invert_elevation!==null&&p.invert_elevation!==undefined?`<div class="hint">Calculated invert: ${fmt(p.invert_elevation,3)}${p.connected_point_id?` · Network connection: ${esc(p.connected_point_id)} (${fmt(p.connection_score,0)}%)`:''}</div>`:(p.connected_point_id?`<div class="hint">Network connection: ${esc(p.connected_point_id)} (${fmt(p.connection_score,0)}%)</div>`:'')}${(p.qc_flags||[]).map(x=>`<div class="hint" style="color:var(--warn)">⚠ ${esc(x)}</div>`).join('')}</div>`;}
function collectPipes(){return $$('.pipe-card',$('#modalBody')).map(c=>({dip:num($('.p-dip',c).value),diameter_in:num($('.p-dia',c).value),material:$('.p-mat',c).value.trim()||null,azimuth_deg:num($('.p-az',c).value),leader_direction_deg:num($('.p-leader',c).value),connected_point_raw:$('.p-to',c).value.trim()||null}));}
function num(v){if(v===''||v===null||v===undefined)return null;const n=Number(v);return Number.isFinite(n)?n:null;}
function reviewEvidenceFor(r){return (r.evidence_records||[])[0]||null;}
async function openResultReview(pointId){if(!resultsLoaded||resultsRevision!==(state?.project_revision??resultsRevision)){try{await refreshResults()}catch(e){toast(`Could not load result details: ${e.message}`,'error');return}}const r=results.find(x=>x.point_id===pointId);if(!r)return;currentReviewPoint=pointId;currentReviewIndex=filteredResults().findIndex(x=>x.point_id===pointId);const ev=reviewEvidenceFor(r);const evidenceScore=ev?Math.round((ev.evidence_score||0)*100):0;const evidenceDecision=ev?.evidence_decision||'MANUAL_REVIEW';const evidenceSources=(ev?.evidence_sources||[]).join(' + ')||'No independent evidence sources';const pageType=(ev?.page_type||'unknown').replaceAll('_',' ');const pageId=ev?.page_id;const bbox=ev?.bbox;const img=pageId?`<div class="evidence-pane"><div class="evidence-toolbar"><div class="evidence-tabs"><button class="img-mode active" data-mode="enhanced">Enhanced</button><button class="img-mode" data-mode="original">Original</button></div><span class="chip">${esc(ev.source_name)} · Page ${ev.page_number}</span></div><div class="image-frame"><div class="image-stage"><img id="reviewImage" src="/api/page/${encodeURIComponent(pageId)}?enhanced=1"/>${bboxHtml(bbox)}</div></div>${ev.ocr_text?`<div class="raw-ocr" style="margin-top:8px">${esc(ev.ocr_text)}</div>`:''}</div>`:`<div class="evidence-pane"><div class="empty-state">No field-book image is linked to this result.</div></div>`;const factors=(r.confidence_factors||[]).map(x=>`<div>• ${esc(x)}</div>`).join('')||'<div>No confidence factors yet.</div>';const qcs=(r.qc_flags||[]).map(x=>`<div>⚠ ${esc(x)}</div>`).join('')||'<div>No deterministic QC flags.</div>';const pointOptions=results.map(x=>`<option value="${esc(x.point_id)}">${esc(x.code||'')} ${esc(x.category||'')}</option>`).join('');const reassignNote=r.point_id_reassigned_from?`<div class="note-box warning"><strong>Reviewer PointID correction</strong><div class="hint">Originally associated with Point ${esc(r.point_id_reassigned_from)}. ${esc(r.point_id_reassignment_note||'')}</div></div>`:r.point_id_reassigned_to?`<div class="note-box"><strong>Evidence moved</strong><div class="hint">Evidence from this record was reassigned to Point ${esc(r.point_id_reassigned_to)}.</div></div>`:'';const html=`<div class="review-layout">${img}<div class="review-form"><div class="review-summary"><div class="summary-chip"><small>Current PointID</small><strong>${esc(r.point_id)}</strong></div><div class="summary-chip"><small>Primary status</small><strong>${esc(r.status)}</strong></div><div class="summary-chip"><small>Dip detail</small><strong>${esc(r.qa_needs_review?'QA REVIEW':r.dip_status)}</strong></div><div class="summary-chip"><small>Smart confidence</small><strong>${fmt(r.smart_confidence,0)}%</strong></div><div class="summary-chip"><small>Evidence decision</small><strong>${esc(evidenceDecision)}</strong></div><div class="summary-chip"><small>Evidence score</small><strong>${evidenceScore}%</strong></div></div>${reassignNote}<div class="note-box" style="margin:10px 0"><b>Evidence sources:</b> ${esc(evidenceSources)}<br/><b>Page type:</b> ${esc(pageType)}${ev?.field_note_template==='BRT_STANDARD'?'<br/><b>Field-note template:</b> BRT standard circle / north arrow / pipe leaders':''}</div><div class="factor-list">${factors}</div><div class="qc-list">${qcs}</div><label>Survey PointID<input id="editPointId" class="control" list="reviewPointList" value="${esc(r.point_id)}" autocomplete="off"/><datalist id="reviewPointList">${pointOptions}</datalist><span class="hint">If the field-book evidence belongs to a different point, choose that imported Survey PointID. SurveySync preserves the original AI/OCR association in the audit history.</span></label><div class="form-grid"><label>Primary status<select id="editStatus" class="control"><option>YES</option><option>NO</option><option>CNA</option><option>CNL</option><option>REVIEW</option><option value="NOT_FOUND">NOT FOUND</option></select></label><label>Dip detail status<select id="editDipStatus" class="control"><option>YES</option><option>NO</option><option>CNA</option><option>CNL</option><option>REVIEW</option><option value="NOT_FOUND">NOT FOUND</option></select></label></div><label>Notes<textarea id="editNotes" class="control" rows="2">${esc(r.notes||'')}</textarea></label><div><div class="row"><strong>Pipes</strong><span class="grow"></span><button id="addPipeBtn" class="btn subtle">+ Pipe</button></div><div id="pipeEditors">${r.pipes.map(pipeEditor).join('')}</div></div><div class="review-actions"><button id="prevResultBtn" class="btn subtle">←</button><button id="nextResultBtn" class="btn subtle">→</button><button id="secondOpinionBtn" class="btn secondary" ${state?.settings?.has_gemini_key?'':'disabled'}>Gemini second opinion</button><button id="attachReviewPhotoBtn" class="btn subtle">Attach Photo</button><span class="grow"></span><button id="saveResultBtn" class="btn secondary">Save <span class="keyhint">E</span></button><button id="acceptResultBtn" class="btn primary">Accept <span class="keyhint">A</span></button></div></div></div>`;openModal(`Point ${r.point_id}`,html,'STRUCTURE REVIEW');$('#editStatus').value=r.status;$('#editDipStatus').value=r.dip_status||'NOT_FOUND';bindReview(r,ev);injectTeachProfileControls(r,ev);if(state?.job?.running&&r.live_preview){const f=$('.review-form',$('#modalBody'));if(f)f.insertAdjacentHTML('afterbegin',`<div class="live-preview-note"><strong>LIVE ANALYSIS PREVIEW</strong><span>${r.live_state==='PENDING_OCR'?'Waiting for OCR':r.live_state==='OCR_FOUND'?'PointID found — Qwen interpretation pending':'Interpretation available'} · edits unlock when analysis finishes.</span></div>`);['#editPointId','#editStatus','#editDipStatus','#editNotes','#addPipeBtn','#saveResultBtn','#acceptResultBtn','#secondOpinionBtn'].forEach(sel=>{const el=$(sel);if(el)el.disabled=true});$$('.pipe-card input',$('#modalBody')).forEach(el=>el.disabled=true)}}
function bindReview(r,ev){function bindRemove(){$$('.remove-pipe',$('#modalBody')).forEach(b=>b.onclick=()=>b.closest('.pipe-card').remove())}bindRemove();$('#addPipeBtn').onclick=()=>{$('#pipeEditors').insertAdjacentHTML('beforeend',pipeEditor({},$$('.pipe-card',$('#pipeEditors')).length));bindRemove()};$$('.img-mode').forEach(b=>b.onclick=()=>{$$('.img-mode').forEach(x=>x.classList.toggle('active',x===b));const img=$('#reviewImage'),stage=img?.closest('.image-stage');if(img)img.src=`/api/page/${encodeURIComponent(ev.page_id)}${b.dataset.mode==='enhanced'?'?enhanced=1':''}`;stage?.classList.toggle('original-mode',b.dataset.mode==='original')});$('#saveResultBtn').onclick=saveCurrentReview;$('#acceptResultBtn').onclick=acceptCurrentReview;$('#secondOpinionBtn').onclick=secondOpinion;$('#attachReviewPhotoBtn').onclick=attachReviewPhoto;$('#prevResultBtn').onclick=()=>moveReview(-1);$('#nextResultBtn').onclick=()=>moveReview(1);}

async function openManualEntryWizard(){
  if(!resultsLoaded){try{await refreshResults()}catch(e){toast(e.message,'error');return}}
  const options=results.map(r=>`<option value="${esc(r.point_id)}">${esc(r.code||'')} ${esc(r.category||'')}</option>`).join('');
  openModal('Manual Field Book Entry',`<div class="feedback-wizard"><div class="eyebrow">REVIEW-FIRST WORKFLOW</div><h2>Enter or correct a structure manually</h2><p class="hint">Use the survey PointID as the authority. This marks the record EDITED and keeps the automated result available in the audit history.</p><label>Survey PointID<input id="manualPointId" class="control" list="manualPointList" placeholder="Start typing a PointID"/><datalist id="manualPointList">${options}</datalist></label><div class="form-grid"><label>Primary status<select id="manualStatus" class="control"><option>YES</option><option>NO</option><option>CNA</option><option>CNL</option><option>REVIEW</option><option value="NOT_FOUND">NOT FOUND</option></select></label><label>Dip detail<select id="manualDipStatus" class="control"><option>YES</option><option>NO</option><option>CNA</option><option>CNL</option><option>REVIEW</option><option value="NOT_FOUND">NOT FOUND</option></select></label></div><label>Reviewer notes<textarea id="manualNotes" class="control" rows="3" placeholder="What is visible in the field book? Page, callout, correction, etc."></textarea></label><div><div class="row"><strong>Pipes / dips</strong><span class="grow"></span><button id="manualAddPipeBtn" class="btn subtle">+ Pipe</button></div><div id="manualPipeEditors"></div></div><div class="review-actions"><span class="grow"></span><button id="manualSaveBtn" class="btn primary">Save Manual Entry</button></div></div>`,'MANUAL REVIEW');
  function bindRemove(){$$('.remove-pipe',$('#modalBody')).forEach(b=>b.onclick=()=>b.closest('.pipe-card').remove())}
  $('#manualAddPipeBtn').onclick=()=>{$('#manualPipeEditors').insertAdjacentHTML('beforeend',pipeEditor({},$$('.pipe-card',$('#manualPipeEditors')).length));bindRemove()};
  $('#manualPointId').addEventListener('change',()=>{const id=$('#manualPointId').value.trim();const r=results.find(x=>x.point_id===id);if(!r)return;$('#manualStatus').value=r.status||'REVIEW';$('#manualDipStatus').value=r.dip_status||'REVIEW';$('#manualNotes').value=r.notes||'';$('#manualPipeEditors').innerHTML=(r.pipes||[]).map(pipeEditor).join('');bindRemove()});
  $('#manualSaveBtn').onclick=async()=>{const id=$('#manualPointId').value.trim();const r=results.find(x=>x.point_id===id);if(!r){toast('Choose an existing survey PointID.','error');return}const btn=$('#manualSaveBtn');btn.disabled=true;btn.textContent='Saving…';try{await api(`/api/results/${encodeURIComponent(id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:$('#manualStatus').value,dip_status:$('#manualDipStatus').value,review_state:'EDITED',notes:$('#manualNotes').value,pipes:collectPipes()})});toast(`Point ${id} saved as a manual review entry.`,'good');closeModal();await loadState();await refreshResults()}catch(e){toast(e.message,'error');btn.disabled=false;btn.textContent='Save Manual Entry'}};
}
function reviewEditPayload(){const newId=document.getElementById('editPointId')?.value.trim()||currentReviewPoint;if(!results.some(x=>x.point_id===newId))throw new Error('Choose an existing imported Survey PointID.');return {point_id:newId,reassignment_reason:newId!==currentReviewPoint?`Reviewer corrected PointID from ${currentReviewPoint} to ${newId} during structure review.`:'',status:$('#editStatus').value,dip_status:$('#editDipStatus').value,review_state:'EDITED',notes:$('#editNotes').value,pipes:collectPipes()}}
