async function attachReviewPhoto(){
  if(!currentReviewPoint)return;
  const path=prompt(`Photo file path for Point ${currentReviewPoint}:`,'');if(!path)return;
  const pipeRaw=prompt('Pipe number this photo documents (leave blank for whole structure):','');
  const pipeIndex=pipeRaw?Number(pipeRaw):null;
  const caption=prompt('Photo caption / QA note:','')||'';
  try{const d=await api('/api/v9/attachments/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_path:path,module:'FieldBookSync',object_type:pipeIndex?'utility_pipe':'utility_structure',object_id:currentReviewPoint,caption,metadata:{point_id:currentReviewPoint,pipe_index:Number.isFinite(pipeIndex)?pipeIndex:null}})});toast(`Attached ${d.filename}`,'good')}catch(e){toast(e.message,'error')}
}

