function updateMapSummary(){const pts=network.structures||[],edges=network.edges||[],live=!!network.live_preview,crs=mapProject.project_crs_name||network.project_crs_name||mapProject.project_crs||network.project_crs||'',a=mapProject.alignment||{};$('#mapSummary').textContent=pts.length?(live?`${pts.length} structures · ${network.candidate_count||0} OCR found · ${network.interpreted_count||0} interpreted · ${edges.length} links`:`${pts.length} structures · ${edges.length} connections · ${(mapProject.layers||[]).length} GIS layer${(mapProject.layers||[]).length===1?'':'s'}`):`${(mapProject.layers||[]).length} GIS layer${(mapProject.layers||[]).length===1?'':'s'} · no survey coordinates`;$('#mapCrsChip').textContent=crs||'Local XY · set CRS for basemaps';const achip=$('#mapAlignmentChip');if(achip)achip.textContent=a.enabled?`${a.label||'Aligned'} · SF ${Number(a.scale_factor||1).toFixed(8)} · R ${Number(a.rotation_deg||0).toFixed(5)}°`:'No alignment';const warn=$('#mapCrsWarning');if(warn){warn.textContent=mapProject.crs_warning||'';warn.classList.toggle('hidden',!mapProject.crs_warning)}$('#mapSelectionChip').textContent=`${mapSelected.size} selected`;$('#mapLayerCount').textContent=(mapProject.layers||[]).length}
function updateScaleBar(){const el=$('#mapScaleBar');if(!el)return;const {w}=mapSize();if(mapView.geo){const mpp=156543.03392*Math.cos(mapView.centerLat*Math.PI/180)/Math.pow(2,mapView.zoom),target=mpp*Math.min(140,w*.18),nice=niceScale(target),px=nice/mpp;el.style.width=`${Math.max(40,px)}px`;el.textContent=nice>=1000?`${fmt(nice/1000,1)} km`:`${Math.round(nice)} m`}else{const target=mapView.localScale*Math.min(140,w*.18),nice=niceScale(target),px=nice/mapView.localScale;el.style.width=`${Math.max(40,px)}px`;el.textContent=`${fmt(nice,1)} ${esc(mapProject.project_units||'units')}`}}
function niceScale(v){const p=Math.pow(10,Math.floor(Math.log10(Math.max(v,1e-9)))),n=v/p;return (n>=5?5:n>=2?2:1)*p}
function renderMapLayerPanel(){const host=$('#mapLayerList');if(!host)return;const layers=mapProject.layers||[];host.innerHTML=layers.length?layers.map((l,i)=>`<div class="map-layer-row" data-layer-row="${esc(l.layer_id)}"><div class="map-layer-top"><input class="layer-vis" type="checkbox" ${l.visible!==false?'checked':''}/><i class="map-layer-color" style="background:${stableColor(l.layer_id)}"></i><strong title="${esc(l.name)}">${esc(l.name)}</strong><button class="icon-btn layer-up" title="Move layer up" ${i===0?'disabled':''}>↑</button><button class="icon-btn layer-down" title="Move layer down" ${i===layers.length-1?'disabled':''}>↓</button><button class="icon-btn layer-zoom" title="Zoom to layer">⌖</button><button class="icon-btn layer-use-crs" title="Use this layer coordinate system">CRS</button><button class="icon-btn layer-delete" title="Remove layer">×</button></div><small>${esc(l.source_type)} · ${l.feature_count||0} feature${Number(l.feature_count||0)===1?'':'s'}${l.source_crs?` · ${esc(l.source_crs)}`:''}</small><div class="map-layer-controls"><input class="layer-opacity" type="range" min="0" max="100" value="${Math.round(Number(l.opacity??.85)*100)}"/><span>${Math.round(Number(l.opacity??.85)*100)}%</span><span></span></div>${l.warning?`<div class="map-layer-warning">${esc(l.warning)}</div>`:''}</div>`).join(''):'<div class="empty-state compact">Import KML, KMZ, Shapefile, GeoJSON, or File GDB.</div>';$$('[data-layer-row]').forEach(row=>{const l=(mapProject.layers||[]).find(x=>x.layer_id===row.dataset.layerRow);$('.layer-vis',row).onchange=async e=>{l.visible=e.target.checked;await saveLayerSetting(l,{visible:l.visible});renderMapCanvas()};$('.layer-opacity',row).oninput=e=>{l.opacity=Number(e.target.value)/100;$('span:nth-child(2)',$('.map-layer-controls',row)).textContent=`${e.target.value}%`;renderMapCanvas()};$('.layer-opacity',row).onchange=()=>saveLayerSetting(l,{opacity:l.opacity});$('.layer-delete',row).onclick=()=>deleteMapLayer(l);$('.layer-zoom',row).onclick=()=>zoomToLayer(l);$('.layer-use-crs',row).onclick=()=>setProjectCrs(l.source_crs);$('.layer-up',row).onclick=()=>moveMapLayer(l.layer_id,-1);$('.layer-down',row).onclick=()=>moveMapLayer(l.layer_id,1)})}
async function saveLayerSetting(layer,payload){try{await api(`/api/map/layers/${encodeURIComponent(layer.layer_id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}catch(e){toast(e.message,'error')}}
