async function setProjectCrs(crs){if(!crs){toast('This layer does not report a coordinate system.','error');return}if(!confirm(`Use ${crs} as the survey/project coordinate system?\n\nOnly do this if the imported survey XY values use the same CRS.`))return;try{const d=await api('/api/map/crs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({crs})});mapProject.project_crs=d.project_crs;mapProject.project_crs_name=d.project_crs_name;mapProject.project_units=d.project_units||'project units';mapView.initialized=false;await loadNetwork();fitMap(false);toast(`Project CRS set from layer: ${d.project_crs_name}`)}catch(e){toast(e.message,'error')}}
async function deleteMapLayer(layer){if(!confirm(`Remove GIS layer “${layer.name}”?`))return;try{await api(`/api/map/layers/${encodeURIComponent(layer.layer_id)}`,{method:'DELETE'});mapProject.layers=(mapProject.layers||[]).filter(x=>x.layer_id!==layer.layer_id);renderNetwork();toast('GIS layer removed')}catch(e){toast(e.message,'error')}}
function zoomToLayer(layer){const b=layer.bounds_wgs84;if(!b)return;pushExtentHistory();mapView.geo=true;mapView.centerLon=(b[0]+b[2])/2;mapView.centerLat=(b[1]+b[3])/2;mapView.zoom=15;mapView.initialized=true;const {w,h}=mapSize(),dx=Math.max(.000001,b[2]-b[0]),dy=Math.max(.000001,b[3]-b[1]);for(let z=19;z>1;z--){const a=lonLatWorld(b[0],b[1],z),c=lonLatWorld(b[2],b[3],z);if(Math.abs(c.x-a.x)<w*.8&&Math.abs(c.y-a.y)<h*.8){mapView.zoom=z;break}}renderMapCanvas()}
function renderBookmarks(){const host=$('#mapBookmarkList');if(!host)return;host.innerHTML=(mapProject.bookmarks||[]).length?(mapProject.bookmarks||[]).map(b=>`<div class="map-bookmark-row"><button class="btn subtle bookmark-go" data-id="${esc(b.bookmark_id)}">${esc(b.name)}</button><button class="icon-btn bookmark-delete" data-id="${esc(b.bookmark_id)}">×</button></div>`).join(''):'<div class="empty-state compact">No bookmarks yet.</div>';$$('.bookmark-go').forEach(b=>b.onclick=()=>{const bm=(mapProject.bookmarks||[]).find(x=>x.bookmark_id===b.dataset.id);if(!bm)return;pushExtentHistory();if(bm.center_lon!=null){mapView.geo=true;mapView.centerLon=bm.center_lon;mapView.centerLat=bm.center_lat;mapView.zoom=bm.zoom}else{mapView.geo=false;mapView.centerX=bm.center_x;mapView.centerY=bm.center_y;mapView.localScale=bm.zoom}renderMapCanvas()});$$('.bookmark-delete').forEach(b=>b.onclick=async()=>{try{await api(`/api/map/bookmarks/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});mapProject.bookmarks=(mapProject.bookmarks||[]).filter(x=>x.bookmark_id!==b.dataset.id);renderBookmarks()}catch(e){toast(e.message,'error')}})}
async function addBookmark(){const name=prompt('Bookmark name','Saved map view');if(!name)return;const payload=mapView.geo?{name,center_lon:mapView.centerLon,center_lat:mapView.centerLat,zoom:mapView.zoom}:{name,center_x:mapView.centerX,center_y:mapView.centerY,zoom:mapView.localScale};try{const b=await api('/api/map/bookmarks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});mapProject.bookmarks.push(b);renderBookmarks();toast('Map bookmark saved')}catch(e){toast(e.message,'error')}}
function bindMapSvgClicks(){const svg=$('#mapOverlay');if(!svg)return;$$('.survey-node',svg).forEach(n=>n.onclick=e=>{e.stopPropagation();const id=n.dataset.point;if(mapTool==='select'){if(e.ctrlKey||e.shiftKey){mapSelected.has(id)?mapSelected.delete(id):mapSelected.add(id)}else mapSelected=new Set([id]);renderMapCanvas();return}showStructurePopup(id,e.clientX,e.clientY)});$$('.network-edge',svg).forEach(n=>n.onclick=e=>{e.stopPropagation();const edge=(network.edges||[])[Number(n.dataset.edge)];if(edge)showEdgePopup(edge,e.clientX,e.clientY)});$$('.gis-feature',svg).forEach(n=>n.onclick=e=>{e.stopPropagation();showGisPopup(n.dataset.layer,Number(n.dataset.feature),e.clientX,e.clientY)})}
function popupAt(html,clientX,clientY){const host=$('#networkMap'),pop=$('#mapPopup');if(!host||!pop)return;const r=host.getBoundingClientRect();pop.innerHTML=html;pop.classList.remove('hidden');pop.style.left=`${Math.max(6,Math.min(r.width-320,(clientX||r.left+80)-r.left+8))}px`;pop.style.top=`${Math.max(6,Math.min(r.height-280,(clientY||r.top+80)-r.top+8))}px`}
