function showStructurePopup(id,x,y){const p=(network.structures||[]).find(q=>q.point_id===id);if(!p)return;const flags=(p.qc_flags||[]).join(', ')||'None';popupAt(`<h4>Structure ${esc(p.point_id)}</h4><dl><dt>Code</dt><dd>${esc(p.code||'')}</dd><dt>Status</dt><dd>${esc(p.status||'')}</dd><dt>Confidence</dt><dd>${fmt(p.smart_confidence,0)}%</dd><dt>Easting</dt><dd>${fmt(p.easting,3)}</dd><dt>Northing</dt><dd>${fmt(p.northing,3)}</dd>${p.lon!=null?`<dt>Lat/Lon</dt><dd>${fmt(p.lat,6)}, ${fmt(p.lon,6)}</dd>`:''}<dt>Elevation</dt><dd>${fmt(p.elevation,2)}</dd><dt>Pipes</dt><dd>${p.pipe_count||0}</dd><dt>QA</dt><dd>${esc(flags)}</dd></dl><div class="map-popup-actions"><button class="btn subtle" data-map-review="${esc(p.point_id)}">Open evidence</button><button class="btn subtle" data-map-select="${esc(p.point_id)}">Select</button></div>`,x,y);$('[data-map-review]','#mapPopup')?.addEventListener('click',()=>openResultReview(id));$('[data-map-select]','#mapPopup')?.addEventListener('click',()=>{mapSelected.add(id);closeMapPopup();renderMapCanvas()})}
function showEdgePopup(edgeOrA,bOrX,xOrY,y){let edge=edgeOrA;if(typeof edgeOrA==='string'){edge=(network.edges||[]).find(e=>e.from_point===edgeOrA&&e.to_point===bOrX)||{from_point:edgeOrA,to_point:bOrX,status:'Connection'};x=xOrY}popupAt(`<h4>${esc(edge.from_point)} → ${esc(edge.to_point)}</h4><dl><dt>Status</dt><dd>${esc(edge.status||'')}</dd><dt>Distance</dt><dd>${fmt(edge.distance,2)}</dd><dt>Score</dt><dd>${edge.manual?'Manual/locked':fmt(edge.score,0)+'%'}</dd><dt>Bearing error</dt><dd>${fmt(edge.bearing_error_deg,1)}°</dd><dt>Reciprocal</dt><dd>${fmt(edge.reciprocal_error_deg,1)}°</dd><dt>Notes</dt><dd>${esc(edge.notes||'')}</dd></dl>`,x,y)}
