function eventMapPoint(e){const host=$('#networkMap'),r=host.getBoundingClientRect(),sx=e.clientX-r.left,sy=e.clientY-r.top;if(mapView.geo){const g=screenGeo(sx,sy);return{sx,sy,lon:g.lon,lat:g.lat}}const p=screenLocal(sx,sy);return{sx,sy,x:p.x,y:p.y}}
function nearestStructureAtScreen(sx,sy,maxPx=12){let best=null,bestD=maxPx;for(const p of network.structures||[]){const P=pointScreen(p),d=Math.hypot(P.x-sx,P.y-sy);if(d<bestD){best=p;bestD=d}}return best}
function addMeasurePoint(e){const p=eventMapPoint(e),snap=nearestStructureAtScreen(p.sx,p.sy,12);if(snap){mapMeasure.points.push(mapView.geo&&snap.lon!=null?{lon:snap.lon,lat:snap.lat}:{x:snap.easting,y:snap.northing})}else{mapMeasure.points.push(mapView.geo?{lon:p.lon,lat:p.lat}:{x:p.x,y:p.y})};if(mapMeasure.type!=='measure-area'&&mapMeasure.points.length>=2)mapMeasure.points=mapMeasure.points.slice(0,2);renderMapCanvas()}
function zoomMapAt(delta,sx=null,sy=null,push=true){const {w,h}=mapSize();sx=sx==null?w/2:sx;sy=sy==null?h/2:sy;if(push)pushExtentHistory();if(mapView.geo){const anchor=screenGeo(sx,sy),newZoom=Math.max(1,Math.min(20,mapView.zoom+delta));mapView.zoom=newZoom;const p=lonLatWorld(anchor.lon,anchor.lat,newZoom),centerWorld={x:p.x-(sx-w/2),y:p.y-(sy-h/2)},c=worldLonLat(centerWorld.x,centerWorld.y,newZoom);mapView.centerLon=c.lon;mapView.centerLat=c.lat}else{const anchor=screenLocal(sx,sy);mapView.localScale=Math.max(1e-9,mapView.localScale*Math.pow(.72,delta));mapView.centerX=anchor.x-(sx-w/2)*mapView.localScale;mapView.centerY=anchor.y+(sy-h/2)*mapView.localScale}mapView.initialized=true;renderMapCanvas()}
