function zoomToScreenRect(x0,y0,x1,y1,out=false){const {w,h}=mapSize(),rw=Math.abs(x1-x0),rh=Math.abs(y1-y0);if(rw<8||rh<8)return;pushExtentHistory();const cx=(x0+x1)/2,cy=(y0+y1)/2;if(mapView.geo){const center=screenGeo(cx,cy),factor=Math.max(1.01,Math.min(w/rw,h/rh)),dz=Math.log2(factor);mapView.centerLon=center.lon;mapView.centerLat=center.lat;mapView.zoom=Math.max(1,Math.min(20,mapView.zoom+(out?-dz:dz)))}else{const center=screenLocal(cx,cy),ratio=Math.max(rw/w,rh/h);mapView.centerX=center.x;mapView.centerY=center.y;mapView.localScale=Math.max(1e-9,mapView.localScale*(out?1/Math.max(.02,ratio):Math.max(.02,ratio)))}mapView.initialized=true;renderMapCanvas()}
function bindMapInteractions(){const host=$('#networkMap');if(!host||host.dataset.bound==='1')return;host.dataset.bound='1';host.addEventListener('wheel',e=>{e.preventDefault();const p=eventMapPoint(e);zoomMapAt(e.deltaY<0?1:-1,p.sx,p.sy,true)},{passive:false});host.addEventListener('pointerdown',e=>{if(e.button!==0)return;closeMapPopup();const p=eventMapPoint(e);if(mapTool==='pan'){host.setPointerCapture(e.pointerId);mapDrag={type:'pan',x0:e.clientX,y0:e.clientY,snapshot:mapSnapshot()};pushExtentHistory()}else if(['select','zoom-box-in','zoom-box-out'].includes(mapTool)){host.setPointerCapture(e.pointerId);mapDrag={type:mapTool,x0:p.sx,y0:p.sy,x1:p.sx,y1:p.sy}}else if(mapTool.startsWith('measure-'))addMeasurePoint(e)});host.addEventListener('pointermove',e=>{const p=eventMapPoint(e);if($('#mapCoordinates'))$('#mapCoordinates').textContent=mapView.geo?`Lat ${fmt(p.lat,6)} · Lon ${fmt(p.lon,6)}`:`E ${fmt(p.x,3)} · N ${fmt(p.y,3)}`;if(!mapDrag)return;if(mapDrag.type==='pan'){const dx=e.clientX-mapDrag.x0,dy=e.clientY-mapDrag.y0,s=mapDrag.snapshot;if(s.geo){const c=lonLatWorld(s.centerLon,s.centerLat,s.zoom),g=worldLonLat(c.x-dx,c.y-dy,s.zoom);mapView.centerLon=g.lon;mapView.centerLat=g.lat}else{mapView.centerX=s.centerX-dx*s.localScale;mapView.centerY=s.centerY+dy*s.localScale}renderMapCanvas()}else if(['select','zoom-box-in','zoom-box-out'].includes(mapDrag.type)){mapDrag.x1=p.sx;mapDrag.y1=p.sy;renderMapCanvas()}});host.addEventListener('pointerup',e=>{if(!mapDrag)return;const d=mapDrag;if(d.type==='select'){const x0=Math.min(d.x0,d.x1),x1=Math.max(d.x0,d.x1),y0=Math.min(d.y0,d.y1),y1=Math.max(d.y0,d.y1);if(!(e.ctrlKey||e.shiftKey))mapSelected.clear();(network.structures||[]).forEach(p=>{const P=pointScreen(p);if(P.x>=x0&&P.x<=x1&&P.y>=y0&&P.y<=y1)mapSelected.add(p.point_id)})}else if(d.type==='zoom-box-in'||d.type==='zoom-box-out'){zoomToScreenRect(d.x0,d.y0,d.x1,d.y1,d.type==='zoom-box-out');setMapTool('pan')}mapDrag=null;renderMapCanvas()});host.addEventListener('dblclick',e=>{if(mapTool==='measure-area'){e.preventDefault();if(mapMeasure.points.length>=3)renderMapCanvas();return}if(mapTool==='pan'||mapTool==='identify'){e.preventDefault();const p=eventMapPoint(e);zoomMapAt(1,p.sx,p.sy,true)}});host.addEventListener('keydown',e=>{if(e.key==='Escape'){mapDrag=null;setMapTool('pan')}});host.addEventListener('dragenter',e=>{e.preventDefault();$('#mapDropHint')?.classList.remove('hidden')});host.addEventListener('dragover',e=>e.preventDefault());host.addEventListener('dragleave',e=>{if(!host.contains(e.relatedTarget))$('#mapDropHint')?.classList.add('hidden')});host.addEventListener('drop',e=>{e.preventDefault();$('#mapDropHint')?.classList.add('hidden');const files=[...(e.dataTransfer?.files||[])];if(files.length)importMapFiles(files)})}
async function importMapFiles(files){const fd=new FormData();files.forEach(f=>fd.append('files',f));if(mapProject.project_crs)fd.append('assume_crs',mapProject.project_crs);try{toast(`Importing ${files.length} GIS file${files.length===1?'':'s'}…`);const d=await api('/api/map/import',{method:'POST',body:fd,timeoutMs:300000});mapProjectLoaded=false;await loadNetwork();toast(`${d.imported} GIS layer${d.imported===1?'':'s'} imported`);fitMap()}catch(e){toast(e.message,'error')}}
async function configureMapCrs(){
  let selected=mapProject.project_crs||'';
  const a=mapProject.alignment||{enabled:false,scale_factor:1,rotation_deg:0,offset_x:0,offset_y:0,origin_x:0,origin_y:0,label:'Survey alignment'};
  const custom=(mapProject.custom_coordinate_systems||[]);
  const customHtml=custom.map(c=>`<button class="crs-search-item custom-crs-item" data-crs="${esc(c.definition)}"><b>${esc(c.name)}</b><small>${esc(c.authority||'Custom')} · ${esc(c.units||'')}</small></button>`).join('')||'<div class="empty-state compact">No custom systems imported yet.</div>';
  openModal('Coordinate System & Alignment Manager',`<div class="crs-manager"><div class="note-box">Original survey Easting/Northing values are never overwritten. FieldBook Sync applies the selected CRS and optional ground/grid or localization transform only for mapping and GIS alignment.</div><div class="crs-manager-grid"><div class="crs-panel"><div class="eyebrow">PROJECT COORDINATE SYSTEM</div><div class="crs-current"><strong>${esc(mapProject.project_crs_name||'Local / Unknown XY')}</strong>${esc(mapProject.project_crs||'No CRS selected')} · ${esc(mapProject.project_units||'project units')}</div><div class="row" style="margin-top:10px"><input id="crsSearch" class="control" style="flex:1" placeholder="Search Missouri East, State Plane, UTM, EPSG, ESRI WKID…"/><button id="crsSearchBtn" class="btn secondary">Search</button></div><div id="crsSearchResults" class="crs-search-results"><div class="empty-state compact">Search the local EPSG/ESRI coordinate-system catalog.</div></div><div class="row" style="margin-top:10px"><button class="btn subtle crs-preset" data-crs="ESRI:102696">Missouri East (US ft)</button><button class="btn subtle crs-preset" data-crs="EPSG:26996">Missouri East (m)</button><button class="btn subtle crs-preset" data-crs="EPSG:4326">WGS84</button></div><label style="display:block;margin-top:10px">Direct EPSG / ESRI WKID / WKT<input id="crsDirect" class="control" value="${esc(selected)}" placeholder="e.g. ESRI:102696 or paste WKT"/></label><div class="row" style="margin-top:10px"><label class="btn secondary file-btn">Import custom .PRJ / WKT<input id="crsImportFile" type="file" accept=".prj,.wkt,.txt,.json"/></label><button id="crsClearBtn" class="btn subtle">Use Local XY</button></div><div class="eyebrow" style="margin-top:16px">CUSTOM SYSTEMS</div><div id="crsCustomList" class="crs-search-results">${customHtml}</div></div><div class="crs-panel"><div class="eyebrow">GROUND / GRID & LOCALIZATION</div><label style="display:flex;gap:8px;align-items:center;margin:8px 0"><input id="alignEnabled" type="checkbox" ${a.enabled?'checked':''}/> Apply survey-to-grid alignment</label><div class="crs-form-grid"><label>Combined scale factor<input id="alignScale" class="control" type="number" step="0.00000001" value="${Number(a.scale_factor||1)}"/></label><label>Rotation / convergence (deg)<input id="alignRotation" class="control" type="number" step="0.000001" value="${Number(a.rotation_deg||0)}"/></label><label>Easting translation<input id="alignOffsetX" class="control" type="number" step="0.001" value="${Number(a.offset_x||0)}"/></label><label>Northing translation<input id="alignOffsetY" class="control" type="number" step="0.001" value="${Number(a.offset_y||0)}"/></label><label>Scale origin X<input id="alignOriginX" class="control" type="number" step="0.001" value="${Number(a.origin_x||0)}"/></label><label>Scale origin Y<input id="alignOriginY" class="control" type="number" step="0.001" value="${Number(a.origin_y||0)}"/></label></div><p class="hint">For Ground → Grid, enter the project combined factor (grid distance / ground distance). Rotation can include grid convergence or a site calibration rotation. Translation/origin support assumed/local coordinates.</p><div class="eyebrow" style="margin-top:16px">CONTROL POINT CALIBRATION</div><p class="hint">Paste two or more control pairs, one per line: <code>name, localX, localY, gridX, gridY</code>. FieldBook Sync solves a least-squares 2D similarity (translation + rotation + scale) and reports residuals.</p><textarea id="controlPairs" class="control control-pairs" placeholder="CP1, 1000, 1000, 807500.123, 1012345.456&#10;CP2, 2000, 1000, 808499.998, 1012348.112"></textarea><div class="row"><button id="solveAlignmentBtn" class="btn secondary">Solve from control</button><span id="alignmentSolveResult" class="hint"></span></div></div></div><div id="crsManagerWarning" class="note-box warning ${mapProject.crs_warning?'':'hidden'}">${esc(mapProject.crs_warning||'')}</div><div class="row" style="justify-content:flex-end"><button id="applyCrsManager" class="btn primary">Apply CRS & Alignment</button></div></div>`,'COORDINATE SYSTEM');
  const choose=(value,name='')=>{selected=value;$('#crsDirect').value=value;$$('.crs-search-item').forEach(x=>x.classList.toggle('selected',x.dataset.crs===value));if(name)$('#crsSearchResults').dataset.selectedName=name};
  $$('.crs-preset').forEach(b=>b.onclick=()=>choose(b.dataset.crs,b.textContent));$$('.custom-crs-item').forEach(b=>b.onclick=()=>choose(b.dataset.crs,b.querySelector('b')?.textContent||'Custom'));
  async function doSearch(){const q=$('#crsSearch').value.trim();if(!q)return;const box=$('#crsSearchResults');box.innerHTML='<div class="empty-state compact">Searching…</div>';try{const d=await api(`/api/map/crs/search?q=${encodeURIComponent(q)}`,{timeoutMs:30000});box.innerHTML=(d.results||[]).length?(d.results||[]).map(r=>`<button class="crs-search-item" data-crs="${esc(r.id)}"><b>${esc(r.name)}</b><small>${esc(r.id)} · ${esc(r.units||'')} ${r.area?.name?`· ${esc(r.area.name)}`:''}</small></button>`).join(''):'<div class="empty-state compact">No matching coordinate systems.</div>';box.querySelectorAll('.crs-search-item').forEach(b=>b.onclick=()=>choose(b.dataset.crs,b.querySelector('b')?.textContent||''))}catch(e){box.innerHTML=`<div class="empty-state compact">${esc(e.message)}</div>`}}
  $('#crsSearchBtn').onclick=doSearch;$('#crsSearch').onkeydown=e=>{if(e.key==='Enter')doSearch()};$('#crsClearBtn').onclick=()=>choose('');
  $('#crsImportFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const d=await api('/api/map/crs/import',{method:'POST',body:fd,timeoutMs:30000});choose(d.coordinate_system.definition,d.coordinate_system.name);toast(`Imported ${d.coordinate_system.name}`,'good');mapProject.custom_coordinate_systems=[...(mapProject.custom_coordinate_systems||[]),d.coordinate_system]}catch(err){toast(err.message,'error')}e.target.value=''};
  $('#solveAlignmentBtn').onclick=async()=>{try{const lines=$('#controlPairs').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),pairs=lines.map(line=>{const p=line.split(/[,\t]+/).map(x=>x.trim());if(p.length<5)throw new Error(`Control line needs 5 values: ${line}`);return{name:p[0],local_x:Number(p[1]),local_y:Number(p[2]),grid_x:Number(p[3]),grid_y:Number(p[4])}});if(pairs.some(p=>![p.local_x,p.local_y,p.grid_x,p.grid_y].every(Number.isFinite)))throw new Error('Control coordinates must be numeric.');const d=await api('/api/map/alignment/solve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pairs})});const sol=d.solution;$('#alignEnabled').checked=true;$('#alignScale').value=sol.scale_factor;$('#alignRotation').value=sol.rotation_deg;$('#alignOffsetX').value=sol.offset_x;$('#alignOffsetY').value=sol.offset_y;$('#alignOriginX').value=sol.origin_x;$('#alignOriginY').value=sol.origin_y;$('#alignmentSolveResult').textContent=`RMS residual ${Number(sol.residual_rms||0).toFixed(4)} project units`;toast(`Solved calibration - RMS ${Number(sol.residual_rms||0).toFixed(4)}`,'good')}catch(e){toast(e.message,'error')}};
  $('#applyCrsManager').onclick=async()=>{try{const crs=$('#crsDirect').value.trim();const align={enabled:$('#alignEnabled').checked,scale_factor:Number($('#alignScale').value)||1,rotation_deg:Number($('#alignRotation').value)||0,offset_x:Number($('#alignOffsetX').value)||0,offset_y:Number($('#alignOffsetY').value)||0,origin_x:Number($('#alignOriginX').value)||0,origin_y:Number($('#alignOriginY').value)||0,label:$('#alignEnabled').checked?'Survey → Grid':'No alignment'};await api('/api/map/alignment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(align)});const d=await api('/api/map/crs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({crs})});mapProjectLoaded=false;mapView.initialized=false;closeModal();await loadNetwork();if(d.warning)toast(d.warning,'warn');else toast(d.project_crs?`Map CRS set: ${d.project_crs_name}`:'Map returned to Local XY','good')}catch(e){toast(e.message,'error')}};
}
function zoomToPoint(id){const p=(network.structures||[]).find(q=>String(q.point_id).toLowerCase()===String(id).toLowerCase());if(!p)return false;pushExtentHistory();if(network.geographic_ready&&p.lon!=null){mapView.geo=true;mapView.centerLon=p.lon;mapView.centerLat=p.lat;mapView.zoom=Math.max(mapView.zoom,18)}else{mapView.geo=false;mapView.centerX=p.easting;mapView.centerY=p.northing;mapView.localScale=Math.min(mapView.localScale||10,5)}mapView.initialized=true;mapSelected=new Set([p.point_id]);renderMapCanvas();return true}
function searchMap(){const q=$('#mapSearchPoint').value.trim().toLowerCase();if(!q)return;const exact=(network.structures||[]).find(p=>String(p.point_id).toLowerCase()===q),partial=exact||(network.structures||[]).find(p=>`${p.point_id} ${p.code}`.toLowerCase().includes(q));if(partial){zoomToPoint(partial.point_id);showStructurePopup(partial.point_id);return}const layerHit=(mapProject.layers||[]).flatMap(l=>(l.features||[]).map((f,i)=>({l,f,i}))).find(x=>JSON.stringify(x.f.properties||{}).toLowerCase().includes(q));if(layerHit){zoomToLayer(layerHit.l);toast(`Found match in ${layerHit.l.name}`);return}toast('No matching PointID, code, or imported feature.','error')}
async function gotoXY(){const raw=prompt('Go to coordinate.\nUse “xy: easting,northing” or “latlon: longitude,latitude”.','xy: ');if(!raw)return;try{const parts=raw.replace(/^\s*(xy|latlon)\s*:\s*/i,'').split(/[, ]+/).filter(Boolean).map(Number);if(parts.length<2||parts.some(v=>!Number.isFinite(v)))throw new Error('Enter two numeric coordinates.');pushExtentHistory();if(/^\s*latlon/i.test(raw)){mapView.geo=true;mapView.centerLon=parts[0];mapView.centerLat=parts[1];mapView.zoom=18}else{if(network.geographic_ready){const d=await api('/api/map/transform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({x:parts[0],y:parts[1],direction:'to_wgs84'})});mapView.geo=true;mapView.centerLon=d.lon;mapView.centerLat=d.lat;mapView.zoom=18}else{mapView.geo=false;mapView.centerX=parts[0];mapView.centerY=parts[1];mapView.localScale=Math.min(mapView.localScale||10,5)}}mapView.initialized=true;renderMapCanvas()}catch(e){toast(e.message,'error')}}
async function connectSelected(){const ids=[...mapSelected];if(ids.length!==2){toast('Select exactly two structures to create a manual connection.','error');return}try{await api('/api/network/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from_point:ids[0],to_point:ids[1],notes:'Manual connection'})});await loadNetwork();toast(`Manual connection ${ids[0]} → ${ids[1]} saved`)}catch(e){toast(e.message,'error')}}
function traceConnected(){const start=[...mapSelected][0];if(!start){toast('Select a structure first.','error');return}const adj={};(network.edges||[]).forEach(e=>{(adj[e.from_point]??=[]).push(e.to_point);(adj[e.to_point]??=[]).push(e.from_point)});const seen=new Set([start]),q=[start];while(q.length){const a=q.shift();for(const b of adj[a]||[])if(!seen.has(b)){seen.add(b);q.push(b)}}mapTrace=seen;mapSelected=new Set(seen);renderNetwork();toast(`${seen.size} connected structure${seen.size===1?'':'s'} traced`)}
function openProfile(){const ids=mapTrace.size?[...mapTrace]:[...mapSelected];if(!ids.length){toast('Select or trace structures first.','error');return}const pts=ids.map(id=>(network.structures||[]).find(p=>p.point_id===id)).filter(Boolean);const withElev=pts.filter(p=>Number.isFinite(Number(p.elevation)));const rows=pts.map(p=>{const inv=(p.pipes||[]).map(x=>x.invert_elevation).filter(v=>v!=null).sort((a,b)=>a-b)[0];return `<tr><td>${esc(p.point_id)}</td><td>${fmt(p.elevation,2)}</td><td>${fmt(inv,2)}</td><td>${p.pipe_count||0}</td></tr>`}).join('');let chart='';if(withElev.length>1){const W=680,H=220,pad=35,vals=withElev.map(p=>+p.elevation),mn=Math.min(...vals),mx=Math.max(...vals),dy=mx-mn||1,points=withElev.map((p,i)=>`${pad+i/(withElev.length-1)*(W-2*pad)},${H-pad-(+p.elevation-mn)/dy*(H-2*pad)}`).join(' ');chart=`<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:220px"><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="3"/>${withElev.map((p,i)=>{const x=pad+i/(withElev.length-1)*(W-2*pad),y=H-pad-(+p.elevation-mn)/dy*(H-2*pad);return `<circle cx="${x}" cy="${y}" r="4" fill="var(--accent)"/><text x="${x+5}" y="${y-6}" font-size="9" fill="var(--text)">${esc(p.point_id)}</text>`}).join('')}</svg>`}openModal('Network profile',`${chart}<div class="table-wrap"><table class="data-table"><thead><tr><th>PointID</th><th>Elevation</th><th>Lowest invert</th><th>Pipes</th></tr></thead><tbody>${rows}</tbody></table></div>`,'MAP PROFILE')}
function exportSelected(){const pts=(network.structures||[]).filter(p=>mapSelected.has(p.point_id));if(!pts.length){toast('Select structures to export.','error');return}let blob,name;if(network.geographic_ready&&pts.every(p=>p.lon!=null)){const fc={type:'FeatureCollection',features:pts.map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lon,p.lat]},properties:{PointID:p.point_id,Code:p.code,Status:p.status,Confidence:p.smart_confidence,Easting:p.easting,Northing:p.northing,Elevation:p.elevation}}))};blob=new Blob([JSON.stringify(fc,null,2)],{type:'application/geo+json'});name='FieldBookSync_Selected.geojson'}else{const csv=['PointID,Easting,Northing,Elevation,Code,Status',...pts.map(p=>[p.point_id,p.easting,p.northing,p.elevation,p.code,p.status].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\r\n');blob=new Blob([csv],{type:'text/csv'});name='FieldBookSync_Selected.csv'}downloadBlob(blob,name)}
function exportMapSvg(){const svg=$('#mapOverlay');if(!svg)return;const {w,h}=mapSize(),copy=svg.cloneNode(true);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');copy.setAttribute('width',w);copy.setAttribute('height',h);const title=document.createElementNS('http://www.w3.org/2000/svg','text');title.setAttribute('x','18');title.setAttribute('y','24');title.setAttribute('font-size','16');title.setAttribute('font-family','Segoe UI,Arial');title.textContent=`FieldBook Sync — ${state?.project_name||'Project'}`;copy.appendChild(title);downloadBlob(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}),'FieldBookSync_Map.svg');toast('Vector map exported. Online basemap tiles are not embedded in the SVG.')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
if($('#mapMode'))$('#mapMode').value=mapMode;$('#mapMode')?.addEventListener('change',e=>{mapMode=e.target.value;localStorage.setItem('fbs-map-mode',mapMode);renderMapLegend();renderMapCanvas()});
$('#basemapSelect')&&(($('#basemapSelect').value=mapBasemap),$('#basemapSelect').onchange=e=>{mapBasemap=e.target.value;localStorage.setItem('fbs-basemap',mapBasemap);if(mapBasemap!=='none'&&!network.geographic_ready&&(network.structures||[]).length)toast('Set the project coordinate system to align survey points with a basemap.','error');renderMapCanvas()});
$('#basemapOpacity')&&(($('#basemapOpacity').value=mapBasemapOpacity),$('#basemapOpacity').oninput=e=>{mapBasemapOpacity=Number(e.target.value);localStorage.setItem('fbs-basemap-opacity',String(mapBasemapOpacity));renderBasemap()});
$('#fitMapBtn').onclick=()=>fitMap();$('#mapZoomIn').onclick=()=>zoomMap(1);$('#mapZoomOut').onclick=()=>zoomMap(-1);$('#mapPrevExtent').onclick=previousExtent;$('#mapNextExtent').onclick=nextExtent;
$$('[data-map-tool]').forEach(b=>b.onclick=()=>setMapTool(b.dataset.mapTool));$('#mapClearGraphics').onclick=()=>{mapSelected.clear();mapTrace.clear();mapMeasure={type:null,points:[]};setMapTool('pan');closeMapPopup();renderNetwork()};
['#mapShowSurvey','#mapShowNetwork','#mapShowLabels','#mapShowAzimuth','#mapShowQa'].forEach(id=>$(id)?.addEventListener('change',renderMapCanvas));
$('#mapLayerFilter')?.addEventListener('input',e=>{mapLayerFilter=e.target.value.trim().toLowerCase();renderMapCanvas()});$('#mapImportBtn').onclick=()=>$('#mapImportFiles').click();$('#mapImportFiles').onchange=e=>{const f=[...e.target.files];e.target.value='';if(f.length)importMapFiles(f)};$('#mapCrsBtn').onclick=configureMapCrs;$('#mapBookmarkBtn').onclick=addBookmark;$('#mapExportBtn').onclick=exportMapSvg;$('#mapSearchBtn').onclick=searchMap;$('#mapSearchPoint').onkeydown=e=>{if(e.key==='Enter')searchMap()};$('#mapGotoXYBtn').onclick=gotoXY;$('#mapConnectBtn').onclick=connectSelected;$('#mapTraceBtn').onclick=traceConnected;$('#mapProfileBtn').onclick=openProfile;$('#mapExportSelectedBtn').onclick=exportSelected;
bindMapInteractions();

// Batch queue ------------------------------------------------------------------
async function loadBatch(){batchJobs=await api('/api/batch');renderBatch();if(batchJobs.some(j=>j.status==='RUNNING'))startBatchPolling();}
function renderBatch(){$('#batchTable tbody').innerHTML=batchJobs.length?batchJobs.map(j=>`<tr><td><strong>${esc(j.name)}</strong>${j.source_summary?`<small class="batch-source">${esc(j.source_summary)}</small>`:''}</td><td>${esc(providerLabel(j.provider))}</td><td><span class="status ${j.status==='COMPLETE'?'YES':j.status==='ERROR'?'NO':j.status==='RUNNING'?'REVIEW':'NOT_FOUND'}">${esc(j.status)}</span></td><td><div class="conf-line"><div class="conf-bar"><i style="width:${Math.round((j.progress||0)*100)}%"></i></div><strong>${Math.round((j.progress||0)*100)}%</strong></div></td><td>${esc(j.error||j.message||'')}</td><td>${j.status==='COMPLETE'?`<button class="btn subtle load-batch" data-id="${j.job_id}">Load</button>`:''}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state">No queued projects.</div></td></tr>';$$('.load-batch').forEach(b=>b.onclick=async()=>{await api(`/api/batch/${b.dataset.id}/load`,{method:'POST'});toast('Loaded completed batch project');await loadState();switchTab('dashboard')})}
$('#addCurrentBatchBtn').onclick=async()=>{try{const name=prompt('Queue name',state?.project_name||'Current Project');if(name===null)return;await api('/api/batch/add-current',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});toast('Project added to batch queue');loadBatch()}catch(e){toast(e.message,'error')}};
$('#batchProjectFiles').onchange=async e=>{if(!e.target.files.length)return;await queueDroppedProjects([...e.target.files]);e.target.value=''};
$('#batchRawSurveyFiles').onchange=e=>{batchRawSurveys=mergeFileLists(batchRawSurveys,[...e.target.files]);batchLabel()};
$('#batchRawFieldbookFiles').onchange=e=>{batchRawFieldbooks=mergeFileLists(batchRawFieldbooks,[...e.target.files]);batchLabel()};
$('#queueRawBatchBtn').onclick=async()=>{const surveys=[...batchRawSurveys],books=[...batchRawFieldbooks];if(!surveys.length||!books.length){toast('Choose or drop both survey files and field-book files first.','error');return}const fd=new FormData();surveys.forEach(f=>fd.append('survey_files',f));books.forEach(f=>fd.append('fieldbook_files',f));if(state?.selected_profile)fd.append('profile_name',state.selected_profile);try{const d=await api('/api/batch/import-raw',{method:'POST',body:fd});const warnings=[...(d.unmatched_surveys||[]),...(d.unmatched_fieldbooks||[])];toast(`${d.added.length} raw job${d.added.length===1?'':'s'} queued${warnings.length?` · ${warnings.length} unmatched file(s)`:''}`,warnings.length?'warn':'good');batchRawSurveys=[];batchRawFieldbooks=[];$('#batchRawSurveyFiles').value='';$('#batchRawFieldbookFiles').value='';batchLabel();await loadBatch()}catch(e){toast(e.message,'error')}};
$('#startBatchBtn').onclick=async()=>{try{await api('/api/batch/start',{method:'POST'});toast('Batch queue started');startBatchPolling()}catch(e){toast(e.message,'error')}};
function startBatchPolling(){if(batchTimer)return;batchTimer=setInterval(async()=>{try{await loadBatch();if(!batchJobs.some(j=>j.status==='RUNNING'||j.status==='QUEUED')){clearInterval(batchTimer);batchTimer=null;toast('Batch queue finished')}}catch{}},1500)}

// Profile editor ---------------------------------------------------------------
function renderProfileList(){const host=$('#profileList');if(!host)return;host.innerHTML=profiles.map(p=>`<button class="profile-item ${p.name===selectedProfileName?'active':''}" data-profile="${esc(p.name)}"><strong>${esc(p.name)}</strong><small>${esc(p.client||'Custom')} · ${p.codes.length} rules</small></button>`).join('');$$('.profile-item',host).forEach(b=>b.onclick=()=>editProfile(b.dataset.profile));}
function codeRow(c={code:'',category:'Structure',match:'exact',include:true}){return `<tr><td><input class="control c-code" value="${esc(c.code)}"/></td><td><input class="control c-cat" value="${esc(c.category||'Structure')}"/></td><td><select class="control c-match"><option value="exact" ${c.match==='exact'?'selected':''}>Exact</option><option value="starts_with" ${c.match==='starts_with'?'selected':''}>Starts with</option><option value="contains" ${c.match==='contains'?'selected':''}>Contains</option></select></td><td><input class="c-inc" type="checkbox" ${c.include!==false?'checked':''}/></td><td><button class="icon-btn del-code">×</button></td></tr>`;}
function bindCodeRows(){$$('.del-code').forEach(b=>b.onclick=()=>b.closest('tr').remove())}
function editProfile(name){const p=profiles.find(x=>x.name===name);if(!p)return;selectedProfileName=name;$('#profileName').value=p.name;$('#profileClient').value=p.client||'';$('#profileNotes').value=p.notes||'';$('#codesTable tbody').innerHTML=p.codes.map(codeRow).join('');bindCodeRows();renderProfileList();$('#deleteProfileBtn').disabled=['MSD','MoDOT','Ameren','IDOT','Lambert'].includes(name)}
$('#newProfileBtn').onclick=()=>{selectedProfileName=null;$('#profileName').value='New Client';$('#profileClient').value='';$('#profileNotes').value='';$('#codesTable tbody').innerHTML=codeRow();bindCodeRows();renderProfileList()};$('#addCodeBtn').onclick=()=>{$('#codesTable tbody').insertAdjacentHTML('beforeend',codeRow());bindCodeRows()};
function collectProfile(){return {name:$('#profileName').value.trim(),client:$('#profileClient').value.trim(),notes:$('#profileNotes').value.trim(),original_name:selectedProfileName,codes:$$('#codesTable tbody tr').map(tr=>({code:$('.c-code',tr).value.trim(),category:$('.c-cat',tr).value.trim()||'Structure',match:$('.c-match',tr).value,include:$('.c-inc',tr).checked})).filter(c=>c.code)}}
$('#saveProfileBtn').onclick=async()=>{try{const p=collectProfile();const d=await api('/api/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});selectedProfileName=d.profile.name;toast(d.survey_invalidated?'Profile saved; survey results were invalidated because the active rules changed.':'Profile saved');await loadState();await loadProfiles();editProfile(selectedProfileName)}catch(e){toast(e.message,'error')}};
$('#deleteProfileBtn').onclick=async()=>{if(!selectedProfileName||!confirm(`Delete ${selectedProfileName}?`))return;try{await api(`/api/profiles/${encodeURIComponent(selectedProfileName)}`,{method:'DELETE'});selectedProfileName=null;toast('Profile deleted');await loadState();await loadProfiles();if(profiles[0])editProfile(profiles[0].name)}catch(e){toast(e.message,'error')}};
$('#exportProfileCsvBtn').onclick=()=>{if(selectedProfileName)location.href=`/api/profiles/${encodeURIComponent(selectedProfileName)}/export-csv`};
$('#profileCsvFile').onchange=()=>{const f=$('#profileCsvFile').files[0];if($('#profileImportFileName'))$('#profileImportFileName').textContent=f?f.name:'CSV or Excel workbook (.xlsx/.xlsm)';if(f&&!$('#profileCsvName').value.trim())$('#profileCsvName').value=f.name.replace(/\.(csv|xlsx|xlsm|xltx|xltm)$/i,'').replace(/[_-]+/g,' ').trim()};
$('#importProfileCsvBtn').onclick=async()=>{const f=$('#profileCsvFile').files[0],name=$('#profileCsvName').value.trim();if(!f||!name){toast('Choose a CSV or Excel file and enter a profile name.','error');return}const fd=new FormData();fd.append('file',f);fd.append('name',name);fd.append('client',name);try{const d=await api('/api/profiles/import',{method:'POST',body:fd});selectedProfileName=d.profile.name;toast(`${d.profile.codes.length} code rule${d.profile.codes.length===1?'':'s'} imported from ${f.name}`);await loadProfiles();editProfile(selectedProfileName)}catch(e){toast(e.message,'error')}};

// Engine settings --------------------------------------------------------------
function selectProvider(p){selectedProvider=p;$$('.engine-card').forEach(c=>c.classList.toggle('selected',c.dataset.provider===p));}
$$('.engine-card').forEach(c=>c.onclick=()=>selectProvider(c.dataset.provider));
if($('#refreshAiStatusBtn'))$('#refreshAiStatusBtn').onclick=()=>refreshMicrosoftAi(true);if($('#enableWindowsOcrBtn'))$('#enableWindowsOcrBtn').onclick=enableWindowsAiOcr;if($('#enableFoundryBtn'))$('#enableFoundryBtn').onclick=enableFoundryLocal;
$('#ollamaProfile')?.addEventListener('change',e=>{const p=e.target.value;if(p==='fast')$('#ollamaModel').value='qwen3-vl:2b-instruct';else if(p==='balanced')$('#ollamaModel').value='qwen3-vl:4b-instruct';else if(p==='maximum')$('#ollamaModel').value='qwen3-vl:8b-instruct';if($('#ollamaRecommendation'))$('#ollamaRecommendation').textContent=p==='maximum'?'Maximum Accuracy uses Qwen3-VL 8B when installed.':p==='balanced'?'Balanced uses Qwen3-VL 4B — the recommended size/accuracy target.':p==='fast'?'Fast uses Qwen3-VL 2B for lower-memory PCs.':'Auto chooses an installed vision model from detected hardware.'});
function applySettingsToUI(){if(!state?.settings)return;const s=state.settings;selectProvider(s.provider);$('#ollamaBaseUrl').value=s.ollama_base_url||'http://127.0.0.1:11434';$('#ollamaModel').value=s.ollama_model||'qwen3-vl:4b-instruct';if($('#ollamaProfile'))$('#ollamaProfile').value=s.ollama_profile||'auto';$('#geminiModel').value=s.gemini_model||'gemini-3.8-flash';if($('#openaiModel'))$('#openaiModel').value=s.openai_model||'gpt-5.6-luna';if($('#anthropicModel'))$('#anthropicModel').value=s.anthropic_model||'claude-sonnet-5';$('#elevationIsRim').checked=!!s.elevation_is_rim;$('#networkDistance').value=s.network_max_distance||1500;$('#networkTolerance').value=s.network_bearing_tolerance||25;$('#statusRule').value=s.status_rule||'POINT_ID_FOUND';if($('#performanceMode'))$('#performanceMode').value=s.performance_mode||'auto';if($('#rodBustEnabled'))$('#rodBustEnabled').checked=s.rod_bust_enabled!==false;if($('#rodBustRadius'))$('#rodBustRadius').value=s.rod_bust_search_radius||15;if($('#rodBustSlope'))$('#rodBustSlope').value=s.rod_bust_max_slope_percent??8;if($('#rodBustTolerance'))$('#rodBustTolerance').value=s.rod_bust_increment_tolerance??0.08;if($('#rodBustNeighbors'))$('#rodBustNeighbors').value=s.rod_bust_min_neighbors||2;$('#geminiStatus').textContent=s.has_gemini_key?'Key in session':'No key';$('#geminiStatus').className='status-pill '+(s.has_gemini_key?'good':'');if($('#openaiStatus')){$('#openaiStatus').textContent=s.has_openai_key?'Key in session':'No key';$('#openaiStatus').className='status-pill '+(s.has_openai_key?'good':'')}if($('#anthropicStatus')){$('#anthropicStatus').textContent=s.has_anthropic_key?'Key in session':'No key';$('#anthropicStatus').className='status-pill '+(s.has_anthropic_key?'good':'')}renderMicrosoftAiStatus(s.ai_status);renderPerformance();}
function renderPerformance(){const perf=state?.performance;if(!perf)return;const h=perf.hardware||{},p=perf.plan||{},o=perf.ocr_cache||{},q=perf.interpretation_cache||{};const mode=(p.effective_mode||'auto').replace(/^./,x=>x.toUpperCase());if($('#performanceStatus'))$('#performanceStatus').textContent=`${mode} · Accuracy First`;if($('#performanceSummary'))$('#performanceSummary').textContent=`${h.physical_cores||'?'} physical / ${h.logical_cores||'?'} logical CPU cores · ${h.available_ram_gb||0} GB RAM available · ${p.enhancement_workers||1} page-prep workers · ${p.paddle_cpu_threads||1} Paddle threads · ${p.prefetch_pages||1}-page RAM prefetch`;if($('#gpuPerformanceSummary')){if(!h.nvidia_gpu){$('#gpuPerformanceSummary').textContent='No NVIDIA GPU detected by nvidia-smi · CPU Paddle will be used.';}else if(h.paddle_windows_gpu_supported){$('#gpuPerformanceSummary').textContent=`NVIDIA GPU detected: ${h.nvidia_gpu_name||'NVIDIA GPU'} · CC ${h.nvidia_compute_capability||'?'} · CUDA ${h.nvidia_driver_cuda||'?'} · ${h.nvidia_vram_gb||0} GB VRAM · Official Paddle Windows GPU runtime supported (${h.paddle_windows_gpu_channel||'compatible channel'}).`;}else{$('#gpuPerformanceSummary').textContent=`NVIDIA GPU detected: ${h.nvidia_gpu_name||'NVIDIA GPU'} · CC ${h.nvidia_compute_capability||'?'} · ${h.nvidia_vram_gb||0} GB VRAM · Paddle OCR will stay on CPU: ${h.paddle_windows_gpu_reason||'GPU runtime compatibility could not be verified.'}`;}}if($('#analysisCacheSummary'))$('#analysisCacheSummary').textContent=`${o.entries||0} OCR page${Number(o.entries||0)===1?'':'s'} + ${q.entries||0} Qwen interpretation${Number(q.entries||0)===1?'':'s'} cached · ${fmtBytes(Number(o.size_bytes||0)+Number(q.size_bytes||0))}`;}
function renderReliability(){const r=state?.reliability||{},j=r.resumable_job||null,btn=$('#resumeJobBtn');if($('#reliabilityStatus')){$('#reliabilityStatus').textContent=state?.job?.running?'Worker active':j?'Resume available':'Ready';$('#reliabilityStatus').className='status-pill '+(j?'warn':'good')}const bits=[];if(r.job_database)bits.push('SQLite job ledger active');if(Number(r.recovered_interrupted_jobs||0))bits.push(`${Number(r.recovered_interrupted_jobs)} interrupted job${Number(r.recovered_interrupted_jobs)===1?'':'s'} recovered at startup`);if(j)bits.push(`Last job: ${j.status} · page ${j.current_page||0}/${j.total_pages||0}`);else bits.push('No matching interrupted job');if(r.validation_baseline_exists)bits.push('accuracy baseline saved');if($('#reliabilitySummary'))$('#reliabilitySummary').textContent=bits.join(' · ');if(btn){btn.disabled=!!state?.job?.running||!j;btn.textContent=j?`Resume ${String(j.provider||'analysis').toUpperCase()} · ${j.current_page||0}/${j.total_pages||0}`:'Resume interrupted job'}if($('#validationCompareBtn'))$('#validationCompareBtn').disabled=!r.validation_baseline_exists;}
async function resumeInterruptedJob(){const btn=$('#resumeJobBtn');if(!state?.reliability?.resumable_job)return;if(btn)btn.disabled=true;try{const d=await api('/api/resume-analysis',{method:'POST'});toast('Interrupted analysis resumed from persistent checkpoints.','good');renderJob(d);startJobPolling();await loadState()}catch(e){toast(e.message,'error');if(btn)btn.disabled=false}}
async function createDiagnosticBundle(){const btn=$('#diagnosticBundleBtn');if(btn){btn.disabled=true;btn.textContent='Building ZIP…'}try{const resp=await fetch('/api/diagnostics/export',{method:'POST'});if(!resp.ok){let msg=`HTTP ${resp.status}`;try{const d=await resp.json();msg=d.detail||msg}catch{}throw new Error(msg)}const blob=await resp.blob();const cd=resp.headers.get('content-disposition')||'';const m=/filename="?([^";]+)"?/i.exec(cd);const name=m?.[1]||'FieldBookSync_Diagnostics.zip';const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);toast('Privacy-safe diagnostic ZIP created.','good')}catch(e){toast(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent='Create diagnostic ZIP'}}}
async function showJobHistory(){try{const d=await api('/api/job-history?limit=30'),jobs=d.jobs||[];openModal('Analysis job history',jobs.length?`<div class="table-wrap"><table><thead><tr><th>Updated</th><th>Provider</th><th>Status</th><th>Progress</th><th>Message</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(new Date(j.updated_at).toLocaleString())}</td><td>${esc(j.provider)}</td><td><span class="status ${j.status==='COMPLETE'?'YES':j.status==='ERROR'?'NO':j.status==='INTERRUPTED'?'REVIEW':'NOT_FOUND'}">${esc(j.status)}</span></td><td>${j.current_page||0}/${j.total_pages||0}</td><td>${esc(j.error_message||j.message||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No analysis jobs recorded yet.</div>','JOB HISTORY')}catch(e){toast(e.message,'error')}}
async function showErrorHistory(){try{const d=await api('/api/error-history?limit=100'),errs=d.errors||[];openModal('Error history',errs.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Code</th><th>Component</th><th>Severity</th><th>Message</th></tr></thead><tbody>${errs.map(e=>`<tr><td>${esc(new Date(e.created_at).toLocaleString())}</td><td><code>${esc(e.code)}</code></td><td>${esc(e.component)}</td><td>${esc(e.severity)}</td><td>${esc(e.message)}${e.recoverable?' · recoverable':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No structured errors recorded.</div>','ERROR HISTORY')}catch(e){toast(e.message,'error')}}
$('#jobHistoryBtn')?.addEventListener('click',showJobHistory);$('#errorHistoryBtn')?.addEventListener('click',showErrorHistory);

async function freezeValidationBaseline(){const name=prompt('Baseline name','Reviewed Ground Truth');if(!name)return;try{const d=await api('/api/validation/baseline',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});toast(`Validation baseline saved · ${d.record_count} structures`,'good');await loadState()}catch(e){toast(e.message,'error')}}
