$('#renameProjectBtn').onclick=async()=>{const name=prompt('Project name',state?.project_name||'Untitled Project');if(!name)return;try{await api('/api/project/name',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});toast('Project renamed');await loadState()}catch(e){toast(e.message,'error')}};
