$('#recentProjectsBtn').onclick=async()=>{try{const ps=await api('/api/projects');openModal('Recent saved projects',ps.length?`<div class="profile-list">${ps.map(p=>`<button class="profile-item recent-project" data-file="${esc(p.filename)}"><strong>${esc(p.name)}</strong><small>${new Date(p.modified_at).toLocaleString()} · ${(p.size/1024/1024).toFixed(1)} MB</small></button>`).join('')}</div>`:'<div class="empty-state">No saved projects yet.</div>','RECENT PROJECTS');$$('.recent-project').forEach(b=>b.onclick=async()=>{try{await api(`/api/project/load/${encodeURIComponent(b.dataset.file)}`,{method:'POST'});closeModal();toast('Project opened');await loadState();await loadProfiles()}catch(e){toast(e.message,'error')}})}catch(e){toast(e.message,'error')}};

