const FBS_MODAL_SIZE_KEY='surveysync-modal-size:fieldbook';
function applyFieldbookModalSize(){const panel=$('#modal')?.querySelector('.modal-panel');if(!panel)return;panel.style.width='';panel.style.height='';try{const saved=JSON.parse(localStorage.getItem(FBS_MODAL_SIZE_KEY)||'{}');if(saved.width)panel.style.width=Math.min(saved.width,window.innerWidth*.96)+'px';if(saved.height)panel.style.height=Math.min(saved.height,window.innerHeight*.94)+'px'}catch{}}
function rememberFieldbookModalSize(){const panel=$('#modal')?.querySelector('.modal-panel');if(!panel||$('#modal')?.classList.contains('hidden'))return;const r=panel.getBoundingClientRect();if(r.width>200&&r.height>150)localStorage.setItem(FBS_MODAL_SIZE_KEY,JSON.stringify({width:Math.round(r.width),height:Math.round(r.height)}))}
function openModal(title,html,eyebrow='FIELD BOOK SYNC'){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;const m=$('#modal');m.classList.toggle('review-modal',String(html||'').includes('review-layout'));applyFieldbookModalSize();m.classList.remove('hidden')}
function closeModal(){rememberFieldbookModalSize();$('#modal').classList.add('hidden');currentReviewPoint=null;currentReviewIndex=-1}$('#modalClose').onclick=closeModal;$('.modal-backdrop').onclick=closeModal;window.addEventListener('beforeunload',rememberFieldbookModalSize);
function openCommand(){$('#commandPalette').classList.remove('hidden');$('#commandInput').value='';$('#commandResults').innerHTML='<div class="empty-state">Start typing to search this project.</div>';setTimeout(()=>$('#commandInput').focus(),0)}function closeCommand(){$('#commandPalette').classList.add('hidden')}$('#globalSearchBtn').onclick=openCommand;$('.command-backdrop').onclick=closeCommand;
$('#commandInput').oninput=()=>{clearTimeout(commandTimer);const q=$('#commandInput').value.trim();if(!q){$('#commandResults').innerHTML='<div class="empty-state">Start typing to search this project.</div>';return}commandTimer=setTimeout(async()=>{try{const hits=await api(`/api/search?q=${encodeURIComponent(q)}`);$('#commandResults').innerHTML=hits.length?hits.map((h,i)=>`<div class="command-item" data-hit="${i}"><span class="command-icon">${h.type==='result'?'✓':h.type==='fieldbook'?'▤':'↔'}</span><div><strong>${esc(h.title)}</strong><small>${esc(h.subtitle)}</small></div></div>`).join(''):'<div class="empty-state">No matches.</div>';$$('.command-item').forEach((el,i)=>el.onclick=()=>{const h=hits[i];closeCommand();if(h.type==='result')openResultReview(h.point_id);else if(h.type==='fieldbook')openPageModal(h.page_id);else {switchTab('map');setTimeout(()=>openResultReview(h.point_id),100)}})}catch(e){$('#commandResults').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}},180)};

