function closeDesktopMenus(){ $$('.desktop-menu').forEach(m=>m.classList.add('hidden')); $$('.menu-trigger').forEach(b=>b.classList.remove('open')); }
if(!window.__fbsMenuBootstrapReady){$$('.menu-trigger').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const m=$('#'+btn.dataset.menu);if(!m)return;const was=!m.classList.contains('hidden');closeDesktopMenus();if(!was){const r=btn.getBoundingClientRect();m.style.left=`${Math.max(4,r.left)}px`;m.style.top=`${r.bottom}px`;m.classList.remove('hidden');btn.classList.add('open')}}));}
document.addEventListener('click',e=>{if(!e.target.closest('.desktop-menu')&&!e.target.closest('.menu-trigger'))closeDesktopMenus()});
