  const cfg=await loadFeedbackConfig();const shared=feedbackSubmitUrl(cfg);const rows=(d.reports||[]).map(r=>{const st=r.sync?.status||'local_only';const canRetry=['pending','local_only'].includes(st)&&shared;return `<div class="feedback-log-row"><div class="feedback-log-top"><span class="chip">${esc(r.report_type||'Report')}</span><span class="feedback-sync ${esc(st)}">${esc(st.replaceAll('_',' '))}</span></div><strong>${esc(r.title||'Untitled')}</strong><small>${esc(r.report_id||'')} · ${esc((r.created_utc||'').replace('T',' ').replace('Z',' UTC'))}</small><p>${esc((r.description||'').slice(0,360))}</p>${r.sync?.error?`<div class="hint warn">${esc(r.sync.error)}</div>`:''}${canRetry?`<button class="btn mini secondary" data-retry-feedback="${esc(r.report_id)}">Retry Intake Sync</button>`:''}</div>`}).join('');
