  $$('[data-retry-feedback]').forEach(b=>b.addEventListener('click',()=>retryFeedbackReport(b.dataset.retryFeedback)));$('#feedbackLogFolderBtn')?.addEventListener('click',openFeedbackFolder);$('#feedbackLogSettingsBtn')?.addEventListener('click',configureFeedbackForm);
