async function openGlobalMapperConverter(){
  let st={installed:false};try{st=await api('/api/global-mapper/status',{timeoutMs:8000})}catch{}
  const statusHtml=st.installed?`<div class="note-box"><b>Global Mapper detected.</b><br/><code>${esc(st.executable||'')}</code></div>`:`<div class="note-box warning"><b>Global Mapper is not detected.</b> Native FieldBook Sync import/export still works. Install Global Mapper or set <code>GLOBAL_MAPPER_EXE</code> to enable this bridge.</div>`;
  openModal('Global Mapper Converter',`<div class="diagnostics">${statusHtml}<p class="hint" style="margin-top:12px">This uses Global Mapper's scripting engine as a format adapter. Choose any file Global Mapper can open, then select a common output or enter a custom Global Mapper export TYPE token.</p><label>Input file<input id="gmConvertFile" class="control" type="file"/></label><label>Preset<select id="gmPreset" class="control"><option value="GEOJSON|.geojson">GeoJSON</option><option value="DWG|.dwg">AutoCAD DWG</option><option value="DXF|.dxf">AutoCAD DXF</option><option value="KML|.kmz">KML/KMZ</option><option value="CSV|.csv">CSV points</option><option value="custom">Custom TYPE…</option></select></label><div id="gmCustomFields" class="two-col hidden"><label>Global Mapper TYPE token<input id="gmExportType" class="control" placeholder="e.g. SHAPEFILE or GEOTIFF"/></label><label>Output extension<input id="gmExtension" class="control" placeholder="e.g. .shp or .tif"/></label></div><div class="row" style="margin-top:14px"><button id="gmConvertBtn" class="btn primary" ${st.installed?'':'disabled'}>Convert & Download</button><button class="btn secondary" onclick="document.querySelector('#modalClose').click()">Close</button></div><div id="gmConvertStatus" class="hint" style="margin-top:10px"></div></div>`,'GLOBAL MAPPER');
  const preset=$('#gmPreset'),custom=$('#gmCustomFields');preset?.addEventListener('change',()=>custom?.classList.toggle('hidden',preset.value!=='custom'));
  $('#gmConvertBtn')?.addEventListener('click',async()=>{const f=$('#gmConvertFile')?.files?.[0];if(!f){toast('Choose a file to convert.','error');return}let type='',ext='';if(preset.value==='custom'){type=($('#gmExportType')?.value||'').trim();ext=($('#gmExtension')?.value||'').trim()}else{[type,ext]=preset.value.split('|')}if(!type||!ext){toast('Choose an output type and extension.','error');return}const b=$('#gmConvertBtn'),msg=$('#gmConvertStatus');b.disabled=true;b.textContent='Converting…';if(msg)msg.textContent='Global Mapper is processing the file…';try{const fd=new FormData();fd.append('file',f);fd.append('export_type',type);fd.append('extension',ext);const resp=await fetch('/api/global-mapper/convert',{method:'POST',body:fd});if(!resp.ok){let m=`HTTP ${resp.status}`;try{const d=await resp.json();m=d.detail||m}catch{}throw new Error(m)}const blob=await resp.blob();const cd=resp.headers.get('content-disposition')||'';const match=/filename="?([^";]+)"?/i.exec(cd);const name=match?.[1]||`converted${ext}`;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);if(msg)msg.textContent=`Complete · ${name}`;toast('Global Mapper conversion complete.','good')}catch(e){if(msg)msg.textContent=e.message;toast(e.message,'error')}finally{b.disabled=false;b.textContent='Convert & Download'}});
}

