async function exitApplication(){
  closeDesktopMenus();
  // Native installed app: ask the pywebview bridge to close the real application
  // window and local service. window.close() is intentionally not used because
  // browsers/WebView2 can ignore it for windows that were not opened by script.
  try{
    if(window.pywebview?.api?.exit_app){
      await window.pywebview.api.exit_app();
      return;
    }
  }catch(e){console.warn('Native exit bridge failed; falling back to HTTP shutdown.',e)}
  // Browser fallback: stop the local FieldBook Sync server, then leave a clear
  // closed-state message because the browser may not allow this tab to close itself.
  try{await fetch('/api/application/exit',{method:'POST',keepalive:true})}catch{}
  document.body.innerHTML='<main style="font-family:Segoe UI,Arial,sans-serif;padding:48px;max-width:760px;margin:auto"><h1>FieldBook Sync closed</h1><p>The local application service has stopped. You can close this tab.</p></main>';
}

