async function openRequestedSurveySyncAction(){
  const q=new URLSearchParams(location.search);
  if(q.get('feedback')==='1'){const kind=q.get('feedback_type')||'';setTimeout(()=>openFeedbackWizard(kind),120)}
  else if(q.get('rod_height_qc')==='1'){$('#rodBustBtn')?.click()}
  else if(q.get('feedback_log')==='1'){setTimeout(()=>openFeedbackLog(),120)}
}


// Field Note Profile Trainer ---------------------------------------------------
function lines(v){return String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}
async function ensureFieldNoteProfiles(){
  if(fieldNoteProfiles.length)return fieldNoteProfiles;
  const d=await api('/api/field-note-profiles');fieldNoteProfiles=d.profiles||[];return fieldNoteProfiles;
}
function fieldNoteProfileById(id){return fieldNoteProfiles.find(p=>p.profile_id===id)||null}
function renderFieldNoteProfileList(){
  const box=$('#fieldNoteProfileList');if(!box)return;
  box.innerHTML=fieldNoteProfiles.length?fieldNoteProfiles.map(p=>`<button class="profile-item field-note-profile-item ${selectedFieldNoteProfileId===p.profile_id?'active':''}" data-fnp="${esc(p.profile_id)}"><strong>${esc(p.name)}</strong><small>${esc(p.job_type||p.client||p.scope)} · ${p.example_count||0} example${Number(p.example_count||0)===1?'':'s'}${p.locked?' · built-in':''}</small></button>`).join(''):'<div class="empty-state compact">No profiles installed.</div>';
  $$('.field-note-profile-item',box).forEach(b=>b.onclick=()=>selectFieldNoteProfile(b.dataset.fnp));
  if($('#fieldNoteProfileCount'))$('#fieldNoteProfileCount').textContent=fieldNoteProfiles.length;
}
function populateActiveFieldNoteProfile(selected='AUTO'){
  const sel=$('#fieldNoteActiveProfile');if(!sel)return;
  sel.innerHTML=`<option value="AUTO">Auto-detect per page</option>`+fieldNoteProfiles.map(p=>`<option value="${esc(p.profile_id)}">${esc(p.name)}</option>`).join('');
  sel.value=selected||'AUTO';
}
function clearFieldNoteEditor(){
  selectedFieldNoteProfileId=null;
  ['fieldNoteName','fieldNoteClient','fieldNoteJobType','fieldNoteId','fieldNoteDescription','fieldNoteCues','fieldNoteVocabulary','fieldNoteRules','fieldNoteFields'].forEach(id=>{const e=$('#'+id);if(e)e.value=''});
  if($('#fieldNoteProfileTitle'))$('#fieldNoteProfileTitle').textContent='New field-note profile';if($('#fieldNoteExampleChip'))$('#fieldNoteExampleChip').textContent='0 examples';
  setFieldNoteEditorLocked(false);renderFieldNoteProfileList();trainerExamples=[];renderTrainerExamples();
}
function setFieldNoteEditorLocked(locked){
  ['fieldNoteName','fieldNoteClient','fieldNoteJobType','fieldNoteId','fieldNoteDescription','fieldNoteCues','fieldNoteVocabulary','fieldNoteRules','fieldNoteFields'].forEach(id=>{const e=$('#'+id);if(e)e.disabled=!!locked});
  if($('#saveFieldNoteProfileBtn'))$('#saveFieldNoteProfileBtn').disabled=!!locked;
  if($('#deleteFieldNoteProfileBtn'))$('#deleteFieldNoteProfileBtn').disabled=!!locked||!selectedFieldNoteProfileId;
  if($('#duplicateFieldNoteProfileBtn'))$('#duplicateFieldNoteProfileBtn').disabled=!selectedFieldNoteProfileId;
  if($('#exportFieldNoteProfileBtn'))$('#exportFieldNoteProfileBtn').disabled=!selectedFieldNoteProfileId;
}
async function selectFieldNoteProfile(id){
  const p=fieldNoteProfileById(id);if(!p)return;selectedFieldNoteProfileId=id;
  $('#fieldNoteProfileTitle').textContent=p.name;$('#fieldNoteName').value=p.name||'';$('#fieldNoteClient').value=p.client||'';$('#fieldNoteJobType').value=p.job_type||'';$('#fieldNoteId').value=p.profile_id||'';$('#fieldNoteDescription').value=p.description||'';$('#fieldNoteCues').value=(p.detection_cues||[]).join('\n');$('#fieldNoteVocabulary').value=(p.vocabulary||[]).join('\n');$('#fieldNoteRules').value=(p.extraction_instructions||[]).join('\n');$('#fieldNoteFields').value=(p.expected_fields||[]).join('\n');$('#fieldNoteExampleChip').textContent=`${p.example_count||0} example${Number(p.example_count||0)===1?'':'s'}`;
  setFieldNoteEditorLocked(!!p.locked);renderFieldNoteProfileList();await loadTrainerExamples(id);
}
function collectFieldNoteProfile(){
  const existing=fieldNoteProfileById(selectedFieldNoteProfileId)||{};const name=$('#fieldNoteName').value.trim();if(!name)throw new Error('Profile name is required.');
  return {profile_id:($('#fieldNoteId').value.trim()||name).toUpperCase().replace(/[^A-Z0-9_-]+/g,'_'),name,client:$('#fieldNoteClient').value.trim(),job_type:$('#fieldNoteJobType').value.trim(),scope:'custom',locked:false,description:$('#fieldNoteDescription').value.trim(),detection_cues:lines($('#fieldNoteCues').value),vocabulary:lines($('#fieldNoteVocabulary').value),expected_fields:lines($('#fieldNoteFields').value),extraction_instructions:lines($('#fieldNoteRules').value),symbols:existing.symbols||[],version:Number(existing.version||1),created_at:existing.created_at||new Date().toISOString(),updated_at:new Date().toISOString(),original_profile_id:selectedFieldNoteProfileId||null};
}
function applyTrainerSourceFilter(sourceName=''){
  trainerSourceContext=sourceName||'';trainerPages=trainerSourceContext?trainerAllPages.filter(p=>p.source_name===trainerSourceContext):[...trainerAllPages];const sourceSel=$('#trainerSourceFilter');if(sourceSel)sourceSel.value=trainerSourceContext;const pageSel=$('#trainerPageSelect');if(pageSel){pageSel.innerHTML=trainerPages.length?trainerPages.map(p=>`<option value="${esc(p.page_id)}">${esc(p.source_name)} · Page ${p.page_number}</option>`).join(''):'<option value="">No imported pages</option>';if(trainerPages.length)pageSel.value=trainerPages[0].page_id;showTrainerPage(pageSel.value)}renderTrainerQuickPreview()}
function renderTrainerQuickPreview(){const box=$('#trainerQuickPreview');if(!box)return;const pages=trainerPages.slice(0,5);box.innerHTML=pages.length?`<div class="hint">Representative pages for training${trainerSourceContext?` · ${esc(trainerSourceContext)}`:''}</div><div class="trainer-preview-strip">${pages.map(p=>`<button class="trainer-preview-thumb" data-page="${esc(p.page_id)}"><img src="${esc(p.enhanced_url||p.url)}" alt="Page ${p.page_number}"/><span>${p.page_number}</span></button>`).join('')}</div>`:'';$$('.trainer-preview-thumb',box).forEach(b=>b.onclick=()=>{const sel=$('#trainerPageSelect');if(sel){sel.value=b.dataset.page;showTrainerPage(b.dataset.page)}})}
async function loadFieldNoteTrainer(){
  try{
    const [d,pages]=await Promise.all([api('/api/field-note-profiles'),api('/api/pages')]);fieldNoteProfiles=d.profiles||[];trainerAllPages=pages||[];populateActiveFieldNoteProfile(d.selected||state?.selected_field_note_profile||'AUTO');const ov=$('#trainerPageProfileOverride');if(ov)ov.innerHTML=`<option value="AUTO">Page profile: Auto</option>`+fieldNoteProfiles.map(p=>`<option value="${esc(p.profile_id)}">Page: ${esc(p.name)}</option>`).join('');
    const sources=[...new Set(trainerAllPages.map(p=>p.source_name).filter(Boolean))];const sourceSel=$('#trainerSourceFilter');if(sourceSel){sourceSel.innerHTML='<option value="">All field books</option>'+sources.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}if(trainerSourceContext&&!sources.includes(trainerSourceContext))trainerSourceContext='';applyTrainerSourceFilter(trainerSourceContext);
    if(!selectedFieldNoteProfileId||!fieldNoteProfileById(selectedFieldNoteProfileId))selectedFieldNoteProfileId=(fieldNoteProfiles.find(p=>p.profile_id==='BRT_STANDARD')||fieldNoteProfiles[0]||{}).profile_id||null;
    renderFieldNoteProfileList();if(selectedFieldNoteProfileId)await selectFieldNoteProfile(selectedFieldNoteProfileId);else clearFieldNoteEditor();
  }catch(e){toast(`Field Note Trainer could not load: ${e.message}`,'error')}
}
function showTrainerPage(pageId){
  trainerAnnotations=[];renderTrainerAnnotations();const img=$('#trainerImage');if(!img)return;const p=trainerPages.find(x=>x.page_id===pageId);if(!p){img.removeAttribute('src');return}const ov=$('#trainerPageProfileOverride');if(ov)ov.value=p.field_note_profile_override||'AUTO';img.onload=()=>renderTrainerBoxes();img.src=p.enhanced_url||p.url;
}
function trainerPageIndex(){return trainerPages.findIndex(p=>p.page_id===$('#trainerPageSelect')?.value)}
function moveTrainerPage(delta){if(!trainerPages.length)return;let i=trainerPageIndex();i=i<0?0:(i+delta+trainerPages.length)%trainerPages.length;$('#trainerPageSelect').value=trainerPages[i].page_id;showTrainerPage(trainerPages[i].page_id)}
function trainerImageGeometry(){const img=$('#trainerImage'),overlay=$('#trainerOverlay');if(!img||!overlay||!img.complete||!img.naturalWidth)return null;const ir=img.getBoundingClientRect(),or=overlay.getBoundingClientRect();return {img,overlay,left:ir.left-or.left,top:ir.top-or.top,width:ir.width,height:ir.height}}
function normalizedTrainerPoint(e){const g=trainerImageGeometry();if(!g)return null;const r=g.overlay.getBoundingClientRect();const x=e.clientX-r.left-g.left,y=e.clientY-r.top-g.top;if(x<0||y<0||x>g.width||y>g.height)return null;return [Math.round(x/g.width*1000),Math.round(y/g.height*1000)]}
function renderTrainerBoxes(){
  const overlay=$('#trainerOverlay'),g=trainerImageGeometry();if(!overlay||!g)return;overlay.innerHTML='';
  trainerAnnotations.forEach((a,i)=>{if(!a.bbox)return;const [x1,y1,x2,y2]=a.bbox,b=document.createElement('div');b.className='trainer-box';b.style.left=`${g.left+x1/1000*g.width}px`;b.style.top=`${g.top+y1/1000*g.height}px`;b.style.width=`${Math.max(2,(x2-x1)/1000*g.width)}px`;b.style.height=`${Math.max(2,(y2-y1)/1000*g.height)}px`;b.innerHTML=`<span>${i+1}. ${esc(a.label)}${a.pipe_index!==null&&a.pipe_index!==undefined?` · Pipe ${a.pipe_index+1}`:''}</span>`;overlay.appendChild(b)});
  if(trainerDrawing?.start&&trainerDrawing?.current){const [x1,y1]=trainerDrawing.start,[x2,y2]=trainerDrawing.current,b=document.createElement('div');b.className='trainer-draft-box';b.style.left=`${g.left+Math.min(x1,x2)/1000*g.width}px`;b.style.top=`${g.top+Math.min(y1,y2)/1000*g.height}px`;b.style.width=`${Math.abs(x2-x1)/1000*g.width}px`;b.style.height=`${Math.abs(y2-y1)/1000*g.height}px`;overlay.appendChild(b)}
}
function renderTrainerAnnotations(){
  const box=$('#trainerAnnotationList');if(!box)return;box.innerHTML=trainerAnnotations.length?trainerAnnotations.map((a,i)=>`<div class="trainer-annotation-item"><div><strong>${i+1}. ${esc(a.label)}${a.pipe_index!==null&&a.pipe_index!==undefined?` · Pipe ${a.pipe_index+1}`:''}</strong><small>${esc(a.text||a.value||'')} · ${a.bbox?`[${a.bbox.join(', ')}]`:'no box'}</small></div><button class="icon-btn trainer-remove-ann" data-i="${i}" title="Remove">×</button></div>`).join(''):'<div class="empty-state compact">Draw a box on the page to add an annotation.</div>';$$('.trainer-remove-ann',box).forEach(b=>b.onclick=()=>{trainerAnnotations.splice(Number(b.dataset.i),1);renderTrainerAnnotations();renderTrainerBoxes()})
}
function trainerPointerDown(e){if(e.button!==0)return;const pt=normalizedTrainerPoint(e);if(!pt)return;trainerDrawing={start:pt,current:pt};e.currentTarget.setPointerCapture?.(e.pointerId);renderTrainerBoxes()}
function trainerPointerMove(e){if(!trainerDrawing)return;const pt=normalizedTrainerPoint(e);if(!pt)return;trainerDrawing.current=pt;renderTrainerBoxes()}
function trainerPointerUp(e){if(!trainerDrawing)return;const end=normalizedTrainerPoint(e)||trainerDrawing.current,start=trainerDrawing.start;trainerDrawing=null;if(!end||Math.abs(end[0]-start[0])<8||Math.abs(end[1]-start[1])<8){renderTrainerBoxes();return}const bbox=[Math.min(start[0],end[0]),Math.min(start[1],end[1]),Math.max(start[0],end[0]),Math.max(start[1],end[1])];const rawPipe=$('#trainerPipeIndex')?.value;const pipe=rawPipe?Math.max(0,Number(rawPipe)-1):null;trainerAnnotations.push({annotation_id:(crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`),label:$('#trainerLabel')?.value||'other',bbox,text:$('#trainerText')?.value.trim()||'',value:$('#trainerText')?.value.trim()||'',pipe_index:Number.isFinite(pipe)?pipe:null,notes:''});renderTrainerAnnotations();renderTrainerBoxes();if($('#trainerText'))$('#trainerText').value=''}
async function saveTrainerExample(){const profileId=selectedFieldNoteProfileId,pageId=$('#trainerPageSelect')?.value;if(!profileId){toast('Select a field-note profile first.','error');return}if(!pageId){toast('Import a field book and choose a page first.','error');return}if(!trainerAnnotations.length&&!confirm('Save this page as a profile example without annotation boxes?'))return;try{await api('/api/field-note-training/examples',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:profileId,page_id:pageId,annotations:trainerAnnotations,notes:$('#trainerExampleNotes')?.value||''})});const source=trainerSourceContext;if(source){await assignFieldbookProfile(source,profileId,'trained');toast('Training example saved and profile assigned to this field book.','good')}else{toast('Training example saved.','good')}trainerAnnotations=[];renderTrainerAnnotations();renderTrainerBoxes();if($('#trainerExampleNotes'))$('#trainerExampleNotes').value='';await loadFieldNoteTrainer()}catch(e){toast(e.message,'error')}}
async function loadTrainerExamples(profileId){try{trainerExamples=await api(`/api/field-note-training/examples?profile_id=${encodeURIComponent(profileId)}`);renderTrainerExamples()}catch(e){trainerExamples=[];renderTrainerExamples()}}
function renderTrainerExamples(){const box=$('#trainerExampleList');if(!box)return;if($('#trainerSavedCount'))$('#trainerSavedCount').textContent=trainerExamples.length;box.innerHTML=trainerExamples.length?trainerExamples.slice(0,40).map(ex=>`<div class="trainer-example-item"><div><strong>${esc(ex.source_name||'Field-book page')} · Page ${ex.page_number||'?'}</strong><small>${esc(ex.origin||'trainer')} · ${(ex.annotations||[]).length} annotation${(ex.annotations||[]).length===1?'':'s'} · ${esc(ex.notes||'')}</small></div><button class="icon-btn trainer-delete-example" data-profile="${esc(ex.profile_id)}" data-example="${esc(ex.example_id)}" title="Delete example">×</button></div>`).join(''):'<div class="empty-state">No examples saved for this profile yet.</div>';$$('.trainer-delete-example',box).forEach(b=>b.onclick=async()=>{if(!confirm('Delete this saved training example?'))return;try{await api(`/api/field-note-training/examples/${encodeURIComponent(b.dataset.profile)}/${encodeURIComponent(b.dataset.example)}`,{method:'DELETE'});await loadTrainerExamples(selectedFieldNoteProfileId);await loadFieldNoteTrainer()}catch(e){toast(e.message,'error')}})}
async function injectTeachProfileControls(r,ev){
  if(!ev?.page_id||state?.job?.running)return;try{await ensureFieldNoteProfiles()}catch{return}const form=$('.review-form',$('#modalBody'));if(!form||$('#teachProfileBox'))return;const detected=(ev.field_note_profile&&fieldNoteProfileById(ev.field_note_profile))?ev.field_note_profile:(ev.field_note_template==='BRT_STANDARD'?'BRT_STANDARD':state?.selected_field_note_profile);const options=fieldNoteProfiles.map(p=>`<option value="${esc(p.profile_id)}" ${p.profile_id===detected?'selected':''}>${esc(p.name)}</option>`).join('');const node=document.createElement('div');node.id='teachProfileBox';node.className='note-box';node.innerHTML=`<div class="row"><div><b>Teach from this correction</b><div class="hint">Store this reviewed page/result as a labeled example for a field-note format.</div></div><span class="grow"></span><select id="teachProfileSelect" class="control" style="max-width:230px">${options}</select><button id="teachProfileBtn" class="btn subtle">Teach this profile</button></div>`;const actions=$('.review-actions',form);form.insertBefore(node,actions);$('#teachProfileBtn').onclick=async()=>{const id=$('#teachProfileSelect')?.value;if(!id)return;const btn=$('#teachProfileBtn');btn.disabled=true;btn.textContent='Saving correction…';try{const saved=await saveCurrentReview({reopen:false});if(!saved)return;btn.textContent='Teaching profile…';await api(`/api/results/${encodeURIComponent(saved.point_id)}/teach-profile`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:id,notes:`Reviewer correction taught from Point ${saved.point_id}.`})});toast('Saved correction added to the field-note profile.','good');fieldNoteProfiles=[];await loadState();await refreshResults();openResultReview(saved.point_id)}catch(e){toast(e.message,'error')}finally{btn.disabled=false;btn.textContent='Teach this profile'}}
}

$('#fieldNoteActiveProfile')?.addEventListener('change',async e=>{try{await api('/api/select-field-note-profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:e.target.value})});if(state)state.selected_field_note_profile=e.target.value;toast(e.target.value==='AUTO'?'Field-note profile auto-detection enabled.':'Field-note profile selected.','good')}catch(err){toast(err.message,'error')}});
$('#newFieldNoteProfileBtn')?.addEventListener('click',clearFieldNoteEditor);
$('#saveFieldNoteProfileBtn')?.addEventListener('click',async()=>{try{const payload=collectFieldNoteProfile();const d=await api('/api/field-note-profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});fieldNoteProfiles=[];selectedFieldNoteProfileId=d.profile.profile_id;toast('Field-note profile saved.','good');await loadFieldNoteTrainer()}catch(e){toast(e.message,'error')}});
$('#duplicateFieldNoteProfileBtn')?.addEventListener('click',async()=>{if(!selectedFieldNoteProfileId)return;const name=prompt('Name for the custom copy',`${fieldNoteProfileById(selectedFieldNoteProfileId)?.name||'Field Note Profile'} Copy`);if(!name)return;try{const d=await api(`/api/field-note-profiles/${encodeURIComponent(selectedFieldNoteProfileId)}/duplicate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({new_name:name})});fieldNoteProfiles=[];selectedFieldNoteProfileId=d.profile.profile_id;toast('Custom profile created.','good');await loadFieldNoteTrainer()}catch(e){toast(e.message,'error')}});
$('#deleteFieldNoteProfileBtn')?.addEventListener('click',async()=>{if(!selectedFieldNoteProfileId||!confirm('Delete this custom field-note profile?'))return;try{await api(`/api/field-note-profiles/${encodeURIComponent(selectedFieldNoteProfileId)}`,{method:'DELETE'});fieldNoteProfiles=[];selectedFieldNoteProfileId=null;await loadFieldNoteTrainer();toast('Field-note profile deleted.','good')}catch(e){toast(e.message,'error')}});
$('#exportFieldNoteProfileBtn')?.addEventListener('click',()=>{if(selectedFieldNoteProfileId)location.href=`/api/field-note-profiles/${encodeURIComponent(selectedFieldNoteProfileId)}/export`});
$('#fieldNoteProfileImport')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const d=await api('/api/field-note-profiles/import',{method:'POST',body:fd});fieldNoteProfiles=[];selectedFieldNoteProfileId=d.profile.profile_id;toast('Field-note profile imported.','good');await loadFieldNoteTrainer()}catch(err){toast(err.message,'error')}finally{e.target.value=''}});
$('#trainerSourceFilter')?.addEventListener('change',e=>applyTrainerSourceFilter(e.target.value));$('#trainerPageSelect')?.addEventListener('change',e=>showTrainerPage(e.target.value));$('#trainerPageProfileOverride')?.addEventListener('change',async e=>{const pageId=$('#trainerPageSelect')?.value;if(!pageId)return;try{await api(`/api/pages/${encodeURIComponent(pageId)}/field-note-profile`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:e.target.value})});const p=trainerPages.find(x=>x.page_id===pageId);if(p)p.field_note_profile_override=e.target.value;toast(e.target.value==='AUTO'?'Page returned to profile auto-detection.':'Page profile override saved.','good')}catch(err){toast(err.message,'error')}});$('#trainerPrevPageBtn')?.addEventListener('click',()=>moveTrainerPage(-1));$('#trainerNextPageBtn')?.addEventListener('click',()=>moveTrainerPage(1));$('#trainerClearAnnotationsBtn')?.addEventListener('click',()=>{if(trainerAnnotations.length&&!confirm('Clear the unsaved annotation boxes?'))return;trainerAnnotations=[];renderTrainerAnnotations();renderTrainerBoxes()});$('#saveTrainingExampleBtn')?.addEventListener('click',saveTrainerExample);
$('#trainerOverlay')?.addEventListener('pointerdown',trainerPointerDown);$('#trainerOverlay')?.addEventListener('pointermove',trainerPointerMove);$('#trainerOverlay')?.addEventListener('pointerup',trainerPointerUp);$('#trainerOverlay')?.addEventListener('pointercancel',()=>{trainerDrawing=null;renderTrainerBoxes()});window.addEventListener('resize',()=>{if(document.querySelector('#tab-training.active'))renderTrainerBoxes()});

// Init ------------------------------------------------------------------------
function hideStartupSplash(){/* Legacy splash retired in SurveySync v9.1.3. */}
async function init(){
  applyProductTheme(startupProductTheme(),false);
  applyAccent(localStorage.getItem(SURVEYSYNC_ACCENT_KEY)||localStorage.getItem('fbs-accent')||'default',false);
  applyTheme(localStorage.getItem(SURVEYSYNC_APPEARANCE_KEY)||localStorage.getItem('fbs-theme')||'system',false);
  await loadSharedUiPrefs();
  applyUiPrefs();
  $('#themeBtn').onclick=cycleTheme;
  $$('.nav-btn').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
  const prefs=uiPrefs();
  hideStartupSplash();
  const watchdog=null; // Compatibility sentinel: legacy splash watchdog retired in SurveySync v9.1.3.
  try{
    await loadState();
    await syncSurveySyncShell();
    if(state.job?.running)startJobPolling();
    const target=(prefs.restoreWorkspace!==false?localStorage.getItem('fbs-last-workspace'):null)||prefs.startPage||'dashboard';
    if(document.querySelector(`#tab-${target}`))switchTab(target);

    // Only after the shell is visible do we start optional filesystem/GPU/network work.
    // Staggering these tasks keeps the WebView/UI message pump responsive on launch.
    setTimeout(()=>signalStartupReady(),150);
    setTimeout(()=>loadProfiles().catch(e=>toast(`Profiles could not load: ${e.message}`,'error')),250);
    setTimeout(()=>refreshFeedbackStatus(),400);
    setTimeout(()=>openRequestedSurveySyncAction(),500);
    setTimeout(()=>refreshGlobalMapperStatus(),650);
    setTimeout(refreshUpdateNotification,1500);
    setTimeout(()=>{if(!state?.job?.running&&!state?.import_job?.running)loadState().catch(()=>{})},3500);
    setInterval(refreshUpdateNotification,6*60*60*1000);
  }catch(e){toast(`Startup error: ${e.message}`,'error')}
  finally{/* FieldBookSync opens directly; SurveySync Home owns What's New. */}
}
init();
